// FVX — Core Computation Model
// 계산 공리 5개의 Go 구현 skeleton
//
// 승계: FreeJulia (lexer, parser, type_system, semantic_analyzer, vm_runtime)
// 확장: 제약 수렴 기반 새 계산 모델

package fvx

import "fmt"

// ============================================================================
// A1 — 상태 존재 (Existence)
// s ∈ S : 값이 아닌 관계망의 교점
// ============================================================================

type StateID uint64

type State struct {
	ID       StateID
	Relations map[string]StateID // 다른 상태와의 관계
	Tags     map[string]string  // 메타데이터
}

func NewState(id StateID) *State {
	return &State{
		ID:        id,
		Relations: make(map[string]StateID),
		Tags:      make(map[string]string),
	}
}

// ============================================================================
// A2 — 자원 보존 (Conservation)
// R(s) = R(s') + δ, δ ≥ 0
// ============================================================================

type ResourceVec struct {
	Memory    float64 // bytes
	Time      float64 // nanoseconds
	Energy    float64 // joules (logical)
	Bandwidth float64 // bytes/sec
}

func (r ResourceVec) Sub(other ResourceVec) ResourceVec {
	return ResourceVec{
		Memory:    r.Memory - other.Memory,
		Time:      r.Time - other.Time,
		Energy:    r.Energy - other.Energy,
		Bandwidth: r.Bandwidth - other.Bandwidth,
	}
}

// Conservation 검증: δ ≥ 0 이어야 함
func (r ResourceVec) IsConserved(after ResourceVec) (bool, ResourceVec) {
	delta := r.Sub(after)
	ok := delta.Memory >= 0 && delta.Time >= 0 &&
		delta.Energy >= 0 && delta.Bandwidth >= 0
	return ok, delta
}

// ============================================================================
// A3 — 제약 완전성 (Constraint Completeness)
// C = { c₁, ..., cₙ },  cᵢ : S × S → Bool
// ============================================================================

type Constraint func(before, after *State) bool

type ConstraintSet struct {
	constraints []namedConstraint
}

type namedConstraint struct {
	name string
	fn   Constraint
}

func NewConstraintSet() *ConstraintSet {
	return &ConstraintSet{}
}

func (cs *ConstraintSet) Add(name string, c Constraint) {
	cs.constraints = append(cs.constraints, namedConstraint{name, c})
}

// 모든 제약 만족 여부 검사
func (cs *ConstraintSet) Satisfied(before, after *State) (bool, string) {
	for _, nc := range cs.constraints {
		if !nc.fn(before, after) {
			return false, nc.name
		}
	}
	return true, ""
}

// ============================================================================
// A4 — 시간 단조성 (Temporal Monotonicity)
// t₁ ≤ t₂ → |feasible(t₂)| ≤ |feasible(t₁)|
// ============================================================================

type Clock uint64 // 단조 증가 시간

type Timeline struct {
	current Clock
}

func (tl *Timeline) Tick() Clock {
	tl.current++
	return tl.current
}

func (tl *Timeline) Now() Clock {
	return tl.current
}

// ============================================================================
// A5 — 관측 불변성 (Observational Invariance)
// π₁ ≡ π₂ if both reach s*
// ============================================================================

type ConvergenceResult struct {
	Stable  *State
	Steps   int
	Cost    ResourceVec
}

// ============================================================================
// 6개 코어 표현식
// ============================================================================

type Expr interface {
	exprNode()
	String() string
}

// state(s) — 상태 참조 (A1)
type ExprState struct {
	ID StateID
}

func (e *ExprState) exprNode() {}
func (e *ExprState) String() string { return fmt.Sprintf("state(%d)", e.ID) }

// consume(e, r) — 자원 소비 (A2)
type ExprConsume struct {
	Inner Expr
	Cost  ResourceVec
}

func (e *ExprConsume) exprNode() {}
func (e *ExprConsume) String() string {
	return fmt.Sprintf("consume(%s, R{mem:%.0f})", e.Inner, e.Cost.Memory)
}

// constrain(e, c) — 제약 부과 (A3)
type ExprConstrain struct {
	Inner      Expr
	Constraint string // 제약 이름
}

func (e *ExprConstrain) exprNode() {}
func (e *ExprConstrain) String() string {
	return fmt.Sprintf("constrain(%s, %s)", e.Inner, e.Constraint)
}

// evolve(e, t) — 시간 전진 (A4)
type ExprEvolve struct {
	Inner Expr
	Until Clock
}

func (e *ExprEvolve) exprNode() {}
func (e *ExprEvolve) String() string {
	return fmt.Sprintf("evolve(%s, t=%d)", e.Inner, e.Until)
}

// observe(e) — 수렴점 관측 (A5)
type ExprObserve struct {
	Inner Expr
}

func (e *ExprObserve) exprNode() {}
func (e *ExprObserve) String() string {
	return fmt.Sprintf("observe(%s)", e.Inner)
}

// compose(e1, e2) — 제약 합성 (all)
type ExprCompose struct {
	Left  Expr
	Right Expr
}

func (e *ExprCompose) exprNode() {}
func (e *ExprCompose) String() string {
	return fmt.Sprintf("compose(%s, %s)", e.Left, e.Right)
}

// ============================================================================
// Solver — 수렴 엔진 (실행 대체)
// ============================================================================

type Solver struct {
	States      map[StateID]*State
	Constraints *ConstraintSet
	Timeline    *Timeline
	MaxSteps    int
}

func NewSolver() *Solver {
	return &Solver{
		States:      make(map[StateID]*State),
		Constraints: NewConstraintSet(),
		Timeline:    &Timeline{},
		MaxSteps:    1000,
	}
}

// Solve: 제약 만족하는 안정 상태 탐색
// 이것이 "실행"을 대체한다
func (sv *Solver) Solve(expr Expr) (*ConvergenceResult, error) {
	steps := 0
	var current *State

	for steps < sv.MaxSteps {
		next, done, err := sv.step(expr, current)
		if err != nil {
			return nil, err
		}
		if done {
			return &ConvergenceResult{
				Stable: next,
				Steps:  steps,
			}, nil
		}
		current = next
		sv.Timeline.Tick()
		steps++
	}

	return nil, fmt.Errorf("수렴 실패: %d steps 초과", sv.MaxSteps)
}

func (sv *Solver) step(expr Expr, current *State) (*State, bool, error) {
	switch e := expr.(type) {
	case *ExprState:
		s, ok := sv.States[e.ID]
		if !ok {
			s = NewState(e.ID)
			sv.States[e.ID] = s
		}
		return s, true, nil

	case *ExprObserve:
		result, done, err := sv.step(e.Inner, current)
		if err != nil {
			return nil, false, err
		}
		if done && current != nil {
			ok, violated := sv.Constraints.Satisfied(current, result)
			if !ok {
				return nil, false, fmt.Errorf("제약 위반: %s", violated)
			}
		}
		return result, done, nil

	case *ExprCompose:
		left, _, err := sv.step(e.Left, current)
		if err != nil {
			return nil, false, err
		}
		return sv.step(e.Right, left)

	case *ExprConstrain:
		return sv.step(e.Inner, current)

	case *ExprEvolve:
		if sv.Timeline.Now() >= e.Until {
			return sv.step(e.Inner, current)
		}
		return current, false, nil

	case *ExprConsume:
		return sv.step(e.Inner, current)
	}

	return nil, false, fmt.Errorf("알 수 없는 표현식: %T", expr)
}

