# ============================================================================
# FVX — A1: 상태 존재 공리 (Existence Axiom)
# 승계: FreeJulia/src/vm_runtime.fl Value 구조 → 재설계
#
# 핵심 변경:
#   기존: Value { type_tag, int_val, float_val, ... }  ← 값 중심
#   신규: State { id, relations, tags }                ← 관계망 교점
#
# s ∈ S 는 값이 아니다. 관계의 교점이다.
# ============================================================================

# 상태 ID (단조 증가)
record StateID {
  value: Int,
}

function new_state_id(v: Int): StateID =
  StateID { value = v }

function state_id_eq(a: StateID, b: StateID): Bool =
  a.value == b.value

# 관계: 다른 상태와의 연결
record Relation {
  name: String,       # 관계 이름 (예: "parent", "type_of", "depends_on")
  target: StateID,    # 대상 상태
}

# 상태: 값이 아닌 관계망의 교점
record State {
  id: StateID,
  relations: Array[Relation],
  tags: Array[(String, String)],  # 메타데이터 (key, value)
}

function new_state(id: StateID): State =
  State {
    id = id,
    relations = [],
    tags = [],
  }

function state_add_relation(s: State, rel: Relation): State =
  State {
    id = s.id,
    relations = array_append(s.relations, rel),
    tags = s.tags,
  }

function state_add_tag(s: State, key: String, val: String): State =
  State {
    id = s.id,
    relations = s.relations,
    tags = array_append(s.tags, (key, val)),
  }

function state_get_tag(s: State, key: String): Option[String] =
  find_tag(s.tags, key)

function find_tag(tags: Array[(String, String)], key: String): Option[String] =
  if array_len(tags) == 0 then None
  else
    let head = array_head(tags)
    if fst(head) == key then Some(snd(head))
    else find_tag(array_tail(tags), key)

# 상태 공간: ID → State 레지스트리
record StateSpace {
  states: Array[(StateID, State)],
  next_id: Int,
}

function new_state_space(): StateSpace =
  StateSpace {
    states = [],
    next_id = 1,
  }

function space_alloc(ss: StateSpace): (StateSpace, State) =
  let id = new_state_id(ss.next_id)
  let s = new_state(id)
  let updated = StateSpace {
    states = array_append(ss.states, (id, s)),
    next_id = ss.next_id + 1,
  }
  (updated, s)

function space_lookup(ss: StateSpace, id: StateID): Option[State] =
  find_state(ss.states, id)

function find_state(pairs: Array[(StateID, State)], id: StateID): Option[State] =
  if array_len(pairs) == 0 then None
  else
    let head = array_head(pairs)
    if state_id_eq(fst(head), id) then Some(snd(head))
    else find_state(array_tail(pairs), id)

