# ============================================================================
# FVX — A2: 자원 보존 공리 (Conservation Axiom)
# 승계: FreeJulia 타입 시스템의 타입 어노테이션 구조 활용
#
# R(s) = R(s') + δ,  δ ≥ 0
# 자원은 생성되지 않는다. 소비되거나 변환될 뿐.
#
# R ∈ ℝ⁺ⁿ: (memory, time, energy, bandwidth)
# δ = 0  → 가역 계산
# δ > 0  → 비가역 계산 (소산)
# ============================================================================

# 자원 벡터 (4차원)
record ResourceVec {
  memory:    Float,    # bytes
  time:      Float,    # nanoseconds (논리적)
  energy:    Float,    # joules (논리적)
  bandwidth: Float,    # bytes/tick
}

function zero_resource(): ResourceVec =
  ResourceVec {
    memory = 0.0,
    time = 0.0,
    energy = 0.0,
    bandwidth = 0.0,
  }

function resource_add(a: ResourceVec, b: ResourceVec): ResourceVec =
  ResourceVec {
    memory    = a.memory + b.memory,
    time      = a.time + b.time,
    energy    = a.energy + b.energy,
    bandwidth = a.bandwidth + b.bandwidth,
  }

function resource_sub(a: ResourceVec, b: ResourceVec): ResourceVec =
  ResourceVec {
    memory    = a.memory - b.memory,
    time      = a.time - b.time,
    energy    = a.energy - b.energy,
    bandwidth = a.bandwidth - b.bandwidth,
  }

# 보존 검사: δ = before - after, δ ≥ 0 이면 OK
record ConservationResult {
  ok:    Bool,
  delta: ResourceVec,
  violated: String,  # 위반 항목 이름 ("" = 없음)
}

function check_conservation(before: ResourceVec, after: ResourceVec): ConservationResult =
  let delta = resource_sub(before, after)
  if delta.memory < 0.0 then
    ConservationResult { ok = false, delta = delta, violated = "memory" }
  else if delta.time < 0.0 then
    ConservationResult { ok = false, delta = delta, violated = "time" }
  else if delta.energy < 0.0 then
    ConservationResult { ok = false, delta = delta, violated = "energy" }
  else if delta.bandwidth < 0.0 then
    ConservationResult { ok = false, delta = delta, violated = "bandwidth" }
  else
    ConservationResult { ok = true, delta = delta, violated = "" }

# 가역성 판정: δ = 0 이면 가역
function is_reversible(result: ConservationResult): Bool =
  result.ok &&
  result.delta.memory == 0.0 &&
  result.delta.time == 0.0 &&
  result.delta.energy == 0.0 &&
  result.delta.bandwidth == 0.0

# 타입에 자원 비용을 포함
# A ⊢ e : B ⊣ ΔR
record TypedResource {
  type_name: String,
  cost:      ResourceVec,
}

function typed_resource(t: String, cost: ResourceVec): TypedResource =
  TypedResource { type_name = t, cost = cost }

