# ============================================================================
# FVX — A3: 제약 완전성 공리 (Constraint Completeness)
# 승계: FreeJulia/src/semantic_analyzer.fl Symbol + Scope 구조 활용
#
# P = { c₁, ..., cₙ },  cᵢ : S × S → Bool
# 프로그램 = 제약 집합
# 실행   = 제약 만족 상태 탐색
# ============================================================================

# 제약 결과
record ConstraintResult {
  satisfied: Bool,
  name:      String,   # 제약 이름
  reason:    String,   # 실패 이유 ("" = 통과)
}

function constraint_pass(name: String): ConstraintResult =
  ConstraintResult { satisfied = true, name = name, reason = "" }

function constraint_fail(name: String, reason: String): ConstraintResult =
  ConstraintResult { satisfied = false, name = name, reason = reason }

# 제약 정의
record Constraint {
  name:     String,
  kind:     String,    # "type", "resource", "temporal", "relation"
  lhs:      String,    # 좌측 상태/표현식 식별자
  rhs:      String,    # 우측 상태/표현식 식별자
  op:       String,    # "eq", "lt", "gt", "le", "ge", "ne", "subtype"
}

function new_constraint(name: String, kind: String, lhs: String, rhs: String, op: String): Constraint =
  Constraint {
    name = name,
    kind = kind,
    lhs = lhs,
    rhs = rhs,
    op = op,
  }

# 제약 집합
record ConstraintSet {
  constraints: Array[Constraint],
}

function new_constraint_set(): ConstraintSet =
  ConstraintSet { constraints = [] }

function cset_add(cs: ConstraintSet, c: Constraint): ConstraintSet =
  ConstraintSet {
    constraints = array_append(cs.constraints, c),
  }

function cset_size(cs: ConstraintSet): Int =
  array_len(cs.constraints)

# 제약 합성: P₁ ∧ P₂
function cset_compose(cs1: ConstraintSet, cs2: ConstraintSet): ConstraintSet =
  ConstraintSet {
    constraints = array_concat(cs1.constraints, cs2.constraints),
  }

# 제약 검증 (심볼 테이블 기반)
# 승계: FreeJulia semantic_analyzer 의 Symbol 검사 로직
record SymbolEnv {
  symbols: Array[(String, String)],  # (이름, 타입)
}

function new_symbol_env(): SymbolEnv =
  SymbolEnv { symbols = [] }

function env_define(env: SymbolEnv, name: String, type_name: String): SymbolEnv =
  SymbolEnv {
    symbols = array_append(env.symbols, (name, type_name)),
  }

function env_lookup(env: SymbolEnv, name: String): Option[String] =
  find_symbol(env.symbols, name)

function find_symbol(syms: Array[(String, String)], name: String): Option[String] =
  if array_len(syms) == 0 then None
  else
    let head = array_head(syms)
    if fst(head) == name then Some(snd(head))
    else find_symbol(array_tail(syms), name)

