  let lhs_type = env_lookup(env, c.lhs)
  let rhs_type = env_lookup(env, c.rhs)
  match (lhs_type, rhs_type) {
    (None, _) =>
      constraint_fail(c.name, "좌측 심볼 미정의: " + c.lhs)
    (_, None) =>
      constraint_fail(c.name, "우측 심볼 미정의: " + c.rhs)
