  else if child == "Int16" && parent == "Integer" then true
  else if child == "Int32" && parent == "Integer" then true
  else if child == "Int64" && parent == "Integer" then true
  else if child == "Float32" && parent == "Floating" then true
  else if child == "Float64" && parent == "Floating" then true
  else if child == "Integer" && parent == "Number" then true
  else if child == "Floating" && parent == "Number" then true
  else false

