# ============================================================================
# FVX — A4: 시간 단조성 공리 (Temporal Monotonicity)
# 승계: FreeJulia vm_runtime.fl 실행 루프 → 수렴 루프로 교체
#
# t₁ ≤ t₂  →  |feasible(t₂)| ≤ |feasible(t₁)|
# 시간 = 자유도 감소 = 결정화(crystallization)
# ============================================================================

# 시간: 단조 증가 클락
record Clock {
  tick: Int,
}

function zero_clock(): Clock =
  Clock { tick = 0 }

function clock_advance(c: Clock): Clock =
  Clock { tick = c.tick + 1 }

function clock_le(a: Clock, b: Clock): Bool =
  a.tick <= b.tick

function clock_lt(a: Clock, b: Clock): Bool =
  a.tick < b.tick

function clock_eq(a: Clock, b: Clock): Bool =
  a.tick == b.tick

# 가능 상태 집합 크기 (추상적 표현)
# 시간이 흐를수록 단조 감소
record Feasibility {
  clock: Clock,
  degree: Int,    # 자유도: 클수록 비결정적, 0이면 수렴
}

function new_feasibility(degree: Int): Feasibility =
  Feasibility {
    clock = zero_clock(),
    degree = degree,
  }

# 시간 전진 + 자유도 감소
function feasibility_step(f: Feasibility, reduction: Int): Feasibility =
  let new_degree = if f.degree - reduction < 0 then 0 else f.degree - reduction
  Feasibility {
    clock = clock_advance(f.clock),
    degree = new_degree,
  }

function is_converged(f: Feasibility): Bool =
  f.degree == 0

# 시간 구간: [start, end]
record TimeInterval {
  start: Clock,
  end_t: Clock,
}

function new_interval(start: Int, end_val: Int): TimeInterval =
  TimeInterval {
    start = Clock { tick = start },
    end_t = Clock { tick = end_val },
  }

function in_interval(c: Clock, interval: TimeInterval): Bool =
  clock_le(interval.start, c) && clock_le(c, interval.end_t)

# 수렴 추적
record ConvergenceTrace {
  steps:       Array[Int],     # 각 단계의 자유도
  converged:   Bool,
  final_clock: Clock,
}

function new_trace(): ConvergenceTrace =
  ConvergenceTrace {
    steps = [],
    converged = false,
    final_clock = zero_clock(),
  }

function trace_step(t: ConvergenceTrace, f: Feasibility): ConvergenceTrace =
  ConvergenceTrace {
    steps = array_append(t.steps, f.degree),
    converged = is_converged(f),
    final_clock = f.clock,
  }

