}

# observe(expr) — 수렴점 관측 (A5)
# 이것이 "실행"을 대체한다
record ExprObserve {
  inner: String,       # 내부 표현식 직렬화
}

# compose(left, right) — 제약 합성 (all)
record ExprCompose {
  left:  String,
  right: String,
}

# ============================================================================
# 표현식 태그 (동적 디스패치)
# 승계: parser.fl 의 노드 타입 판별 패턴
