function expr_consume(inner: Expr, memory: Float, time_c: Float, energy: Float, bw: Float): Expr =
  Expr {
    tag = "consume",
    payload = inner.tag + ":" + inner.payload + "|" +
              float_to_str(memory) + "," +
              float_to_str(time_c) + "," +
              float_to_str(energy) + "," +
              float_to_str(bw),
  }

function expr_constrain(inner: Expr, cname: String): Expr =
  Expr {
    tag = "constrain",
    payload = inner.tag + ":" + inner.payload + "|" + cname,
  }

function expr_evolve(inner: Expr, until_tick: Int): Expr =
  Expr {
    tag = "evolve",
    payload = inner.tag + ":" + inner.payload + "|" + int_to_str(until_tick),
  }

function expr_observe(inner: Expr): Expr =
  Expr {
    tag = "observe",
    payload = inner.tag + ":" + inner.payload,
  }

function expr_compose(left: Expr, right: Expr): Expr =
  Expr {
    tag = "compose",
    payload = left.tag + ":" + left.payload + "||" + right.tag + ":" + right.payload,
  }

# 표현식 문자열 표현 (디버깅)
function expr_to_string(e: Expr): String =
  e.tag + "(" + e.payload + ")"

