# ============================================================================
# FVX — Solver: 수렴 엔진 (Convergence Engine)
# 승계: FreeJulia/src/vm_runtime.fl 실행 루프 → 완전 교체
#
# 기존 VM:   바이트코드 순차 실행
# FVX Solver: 제약 만족 → 수렴점 탐색
#
# Program = Equation System
# Execution = Convergence
# ============================================================================

# ============================================================================
# 수렴 결과
# ============================================================================

record SolveResult {
  ok:          Bool,
  state_id:    Int,    # 수렴한 상태 ID
  steps:       Int,    # 소요 단계 수
  error:       String, # 실패 이유 ("" = 성공)
}

function solve_ok(state_id: Int, steps: Int): SolveResult =
  SolveResult {
    ok = true,
    state_id = state_id,
    steps = steps,
    error = "",
  }

function solve_fail(reason: String, steps: Int): SolveResult =
  SolveResult {
    ok = false,
    state_id = -1,
    steps = steps,
    error = reason,
  }

# ============================================================================
# 솔버 컨텍스트
# ============================================================================

record SolverCtx {
  max_steps:    Int,
  current_tick: Int,
  resource_cap: Float,   # 최대 허용 자원 소비
}

function new_solver_ctx(): SolverCtx =
  SolverCtx {
    max_steps = 1000,
    current_tick = 0,
    resource_cap = 1000000.0,
  }

function ctx_tick(ctx: SolverCtx): SolverCtx =
  SolverCtx {
    max_steps = ctx.max_steps,
    current_tick = ctx.current_tick + 1,
    resource_cap = ctx.resource_cap,
  }

# ============================================================================
# 핵심: Solve 함수 (실행을 대체)
#
# 승계: vm_runtime.fl execute_bytecode() → solve()로 교체
# 핵심 차이:
#   기존: for each instruction → execute
#   신규: while not converged → step toward constraint satisfaction
# ============================================================================

function solve(expr_tag: String, expr_payload: String, ctx: SolverCtx): SolveResult =
  solve_step(expr_tag, expr_payload, ctx, 0)

function solve_step(tag: String, payload: String, ctx: SolverCtx, steps: Int): SolveResult =
  if steps >= ctx.max_steps then
    solve_fail("수렴 실패: max_steps(" + int_to_str(ctx.max_steps) + ") 초과", steps)
  else
    match tag {
      "state" =>
        # 상태 참조: 즉시 수렴 (A1)
        let id = str_to_int(payload)
        solve_ok(id, steps + 1)

      "observe" =>
        # 수렴점 관측 (A5): 내부 표현식을 수렴시키고 결과 반환
        let parts = split_first(payload, ":")
        let inner_tag = fst(parts)
        let inner_payload = snd(parts)
        solve_step(inner_tag, inner_payload, ctx, steps + 1)

      "constrain" =>
        # 제약 부과 (A3): 제약 확인 후 내부 수렴
        let parts = split_pipe(payload)
        let inner_part = fst(parts)
        let inner_parts = split_first(inner_part, ":")
        let inner_tag = fst(inner_parts)
        let inner_payload = snd(inner_parts)
        let result = solve_step(inner_tag, inner_payload, ctx, steps + 1)
        if result.ok then result
        else solve_fail("제약 위반: " + snd(parts), steps)

      "consume" =>
        # 자원 소비 (A2): 자원 검사 후 내부 수렴
        let parts = split_pipe(payload)
        let inner_part = fst(parts)
        let inner_parts = split_first(inner_part, ":")
        let inner_tag = fst(inner_parts)
        let inner_payload = snd(inner_parts)
        solve_step(inner_tag, inner_payload, ctx_tick(ctx), steps + 1)

      "evolve" =>
        # 시간 전진 (A4): until_tick 도달 시까지 반복
        let parts = split_pipe(payload)
        let inner_part = fst(parts)
        let until_tick = str_to_int(snd(parts))
        if ctx.current_tick >= until_tick then
          let inner_parts = split_first(inner_part, ":")
          solve_step(fst(inner_parts), snd(inner_parts), ctx, steps + 1)
        else
          solve_step("evolve", payload, ctx_tick(ctx), steps + 1)

      "compose" =>
        # 제약 합성 (all): 좌→우 순서로 수렴
        let sides = split_double_pipe(payload)
        let left_parts = split_first(fst(sides), ":")
        let left_result = solve_step(fst(left_parts), snd(left_parts), ctx, steps + 1)
        if left_result.ok then
          let right_parts = split_first(snd(sides), ":")
          solve_step(fst(right_parts), snd(right_parts), ctx, left_result.steps)
        else
          left_result

      _ =>
        solve_fail("알 수 없는 표현식 태그: " + tag, steps)
    }

# ============================================================================
# 문자열 유틸 (승계: lexer.fl 의 문자열 처리 패턴)
# ============================================================================

function split_first(s: String, sep: String): (String, String) =
  let idx = string_index_of(s, sep)
  if idx < 0 then (s, "")
  else
    let left = string_slice(s, 0, idx)
    let right = string_slice(s, idx + string_len(sep), string_len(s))
    (left, right)

function split_pipe(s: String): (String, String) =
  split_first(s, "|")

function split_double_pipe(s: String): (String, String) =
  split_first(s, "||")

