# ============================================================================
# FVX — 공리 검증 테스트
# 승계: FreeJulia 각 모듈의 test 파일 구조 활용
# ============================================================================

# ============================================================================
# A1 테스트: 상태는 값이 아니라 관계망 교점
# ============================================================================

function test_a1_state_is_relation(): Bool =
  let ss = new_state_space()
  let result = space_alloc(ss)
  let ss2 = fst(result)
  let s = snd(result)
  # 상태는 ID와 관계망만 가짐 (값 없음)
  let s2 = state_add_relation(s, Relation { name = "type_of", target = StateID { value = 999 } })
  let s3 = state_add_tag(s2, "kind", "integer")
  let tag = state_get_tag(s3, "kind")
  match tag {
    Some(v) => v == "integer"
    None => false
  }

# ============================================================================
# A2 테스트: 자원은 생성되지 않음
# ============================================================================

function test_a2_conservation(): Bool =
  let before = ResourceVec { memory = 100.0, time = 50.0, energy = 10.0, bandwidth = 0.0 }
  let after  = ResourceVec { memory = 60.0,  time = 30.0, energy = 8.0,  bandwidth = 0.0 }
  let result = check_conservation(before, after)
  result.ok && result.delta.memory == 40.0

function test_a2_violation(): Bool =
  let before = ResourceVec { memory = 10.0, time = 5.0, energy = 1.0, bandwidth = 0.0 }
  let after  = ResourceVec { memory = 20.0, time = 5.0, energy = 1.0, bandwidth = 0.0 }  # 메모리 증가 = 위반
  let result = check_conservation(before, after)
  result.ok == false && result.violated == "memory"

function test_a2_reversible(): Bool =
  let r = ResourceVec { memory = 100.0, time = 50.0, energy = 10.0, bandwidth = 0.0 }
  let result = check_conservation(r, r)  # 같으면 δ = 0 = 가역
  is_reversible(result)

# ============================================================================
# A3 테스트: 제약 집합
# ============================================================================

function test_a3_subtype(): Bool =
  is_subtype("Int32", "Integer") &&
  is_subtype("Integer", "Number") &&
  is_subtype("Float64", "Floating") &&
  is_subtype("Any", "Any") &&
  is_subtype("Int32", "Any")

function test_a3_not_subtype(): Bool =
  is_subtype("Int32", "Float64") == false &&
  is_subtype("String", "Number") == false

function test_a3_symbol_env(): Bool =
  let env = new_symbol_env()
  let env2 = env_define(env, "x", "Int32")
  let env3 = env_define(env2, "y", "Float64")
  let c = new_constraint("c1", "type", "x", "y", "eq")
  let result = check_type_constraint(c, env3)
  result.satisfied == false  # Int32 != Float64

# ============================================================================
# A4 테스트: 시간 단조성
# ============================================================================

function test_a4_monotone(): Bool =
  let f0 = new_feasibility(10)
  let f1 = feasibility_step(f0, 3)
  let f2 = feasibility_step(f1, 3)
  let f3 = feasibility_step(f2, 4)
  f0.degree == 10 &&
  f1.degree == 7 &&
  f2.degree == 4 &&
  is_converged(f3)

# ============================================================================
# A5 테스트: Solver 수렴
# ============================================================================

function test_a5_simple_state(): Bool =
  let ctx = new_solver_ctx()
  let result = solve("state", "42", ctx)
  result.ok && result.state_id == 42

function test_a5_observe(): Bool =
  let ctx = new_solver_ctx()
  let result = solve("observe", "state:7", ctx)
  result.ok && result.state_id == 7

function test_a5_compose(): Bool =
  let ctx = new_solver_ctx()
  let result = solve("compose", "state:1||state:2", ctx)
  result.ok && result.state_id == 2

function test_a5_max_steps(): Bool =
  let ctx = SolverCtx { max_steps = 2, current_tick = 0, resource_cap = 1000.0 }
  # evolve until tick=100 → 2 step 안에 수렴 불가
  let result = solve("evolve", "state:1|100", ctx)
  result.ok == false

# ============================================================================
# 테스트 실행
# ============================================================================

function run_all_tests(): Int =
  let results = [
    ("A1 상태=관계망",       test_a1_state_is_relation()),
    ("A2 자원보존 OK",       test_a2_conservation()),
    ("A2 자원보존 위반",     test_a2_violation()),
    ("A2 가역 계산",         test_a2_reversible()),
    ("A3 서브타입 OK",       test_a3_subtype()),
    ("A3 서브타입 실패",     test_a3_not_subtype()),
    ("A3 심볼 환경",         test_a3_symbol_env()),
    ("A4 단조 감소",         test_a4_monotone()),
    ("A5 상태 수렴",         test_a5_simple_state()),
    ("A5 observe",           test_a5_observe()),
    ("A5 compose",           test_a5_compose()),
    ("A5 최대 스텝 초과",    test_a5_max_steps()),
  ]
  count_pass(results, 0)

function count_pass(results: Array[(String, Bool)], acc: Int): Int =
  if array_len(results) == 0 then acc
  else
    let head = array_head(results)
    let name = fst(head)
    let ok = snd(head)
    let _ = if ok then print("[PASS] " + name)
            else print("[FAIL] " + name)
    count_pass(array_tail(results), if ok then acc + 1 else acc)

let total = 12
let passed = run_all_tests()
let _ = print("===================")
let _ = print("결과: " + int_to_str(passed) + "/" + int_to_str(total) + " PASS")

