# ============================================================================
# FVX — IR: 방정식 그래프 (Equation Graph)
# Phase 1 신규
#
# 기존 IR: 선형 명령 시퀀스 (bytecode)
# FVX  IR: 방정식 노드 그래프
#
# 노드 = 제약 방정식
# 엣지 = 의존 관계 (데이터 흐름 아님, 제약 전파)
# 실행 = 그래프 수렴 탐색
# ============================================================================

# ============================================================================
# IR 노드 종류
# ============================================================================

let IR_STATE      = "IR_STATE"      # 상태 노드 (A1)
let IR_RESOURCE   = "IR_RESOURCE"   # 자원 노드 (A2)
let IR_CONSTRAINT = "IR_CONSTRAINT" # 제약 노드 (A3)
let IR_TEMPORAL   = "IR_TEMPORAL"   # 시간 노드 (A4)
let IR_OBSERVE    = "IR_OBSERVE"    # 관측 노드 (A5)
let IR_COMPOSE    = "IR_COMPOSE"    # 합성 노드 (all)

# ============================================================================
# IR 노드
# ============================================================================

record IRNode {
  id:       Int,
  kind:     String,     # IR_* 상수
  label:    String,     # 사람이 읽는 이름
  payload:  String,     # 직렬화된 내용
}

function new_ir_node(id: Int, kind: String, label: String, payload: String): IRNode =
  IRNode { id = id, kind = kind, label = label, payload = payload }

# ============================================================================
# IR 엣지 (제약 전파 방향)
# ============================================================================

let EDGE_DEPENDS   = "DEPENDS"    # a → b: a가 b에 의존
let EDGE_PRODUCES  = "PRODUCES"   # a → b: a가 b를 생성
let EDGE_CONSTRAINS = "CONSTRAINS" # a → b: a가 b를 제약

record IREdge {
  from:  Int,     # 소스 노드 ID
  to:    Int,     # 대상 노드 ID
  kind:  String,  # EDGE_* 상수
  label: String,
}

function new_edge(from: Int, to: Int, kind: String, label: String): IREdge =
  IREdge { from = from, to = to, kind = kind, label = label }

# ============================================================================
# IR 그래프
# ============================================================================

record IRGraph {
  nodes:   Array[IRNode],
  edges:   Array[IREdge],
  next_id: Int,
}

function new_graph(): IRGraph =
  IRGraph {
    nodes   = [],
    edges   = [],
    next_id = 1,
  }

function graph_add_node(g: IRGraph, kind: String, label: String, payload: String): (IRGraph, Int) =
  let id = g.next_id
  let node = new_ir_node(id, kind, label, payload)
  let g2 = IRGraph {
    nodes   = array_append(g.nodes, node),
    edges   = g.edges,
    next_id = id + 1,
  }
  (g2, id)

function graph_add_edge(g: IRGraph, from: Int, to: Int, kind: String, label: String): IRGraph =
  let edge = new_edge(from, to, kind, label)
  IRGraph {
    nodes   = g.nodes,
    edges   = array_append(g.edges, edge),
    next_id = g.next_id,
  }

function graph_node_count(g: IRGraph): Int =
  array_len(g.nodes)

function graph_edge_count(g: IRGraph): Int =
  array_len(g.edges)

function graph_find_node(g: IRGraph, id: Int): Option[IRNode] =
  find_node_in(g.nodes, id)

function find_node_in(nodes: Array[IRNode], id: Int): Option[IRNode] =
  if array_len(nodes) == 0 then None
  else
    let head = array_head(nodes)
    if head.id == id then Some(head)
    else find_node_in(array_tail(nodes), id)

# 특정 노드로 들어오는 엣지
function graph_in_edges(g: IRGraph, node_id: Int): Array[IREdge] =
  filter_edges(g.edges, node_id, true)

# 특정 노드에서 나가는 엣지
function graph_out_edges(g: IRGraph, node_id: Int): Array[IREdge] =
  filter_edges(g.edges, node_id, false)

function filter_edges(edges: Array[IREdge], node_id: Int, is_in: Bool): Array[IREdge] =
  if array_len(edges) == 0 then []
  else
    let head = array_head(edges)
    let tail = filter_edges(array_tail(edges), node_id, is_in)
    let matches = if is_in then head.to == node_id else head.from == node_id
    if matches then array_prepend(tail, head) else tail

# ============================================================================
# IR 빌더: Expr → IRGraph
# 승계: FreeJulia/src/ir_builder.fl 구조 활용 + 재설계
# ============================================================================

record IRBuilder {
  graph: IRGraph,
}

function new_builder(): IRBuilder =
  IRBuilder { graph = new_graph() }

# state(id) → IR_STATE 노드
function build_state(b: IRBuilder, state_id: Int): (IRBuilder, Int) =
  let result = graph_add_node(b.graph, IR_STATE, "state_" + int_to_str(state_id), int_to_str(state_id))
  let g2 = fst(result)
  let nid = snd(result)
  (IRBuilder { graph = g2 }, nid)

# consume(inner, resource) → IR_RESOURCE → IR_OBSERVE 연결
function build_consume(b: IRBuilder, inner_id: Int, memory: Float, time_c: Float): (IRBuilder, Int) =
  let payload = float_to_str(memory) + "," + float_to_str(time_c)
  let result = graph_add_node(b.graph, IR_RESOURCE, "consume", payload)
  let g2 = fst(result)
  let nid = snd(result)
  let g3 = graph_add_edge(g2, inner_id, nid, EDGE_PRODUCES, "resource_flow")
  (IRBuilder { graph = g3 }, nid)

# constrain(inner, cname) → IR_CONSTRAINT 노드
function build_constrain(b: IRBuilder, inner_id: Int, cname: String): (IRBuilder, Int) =
  let result = graph_add_node(b.graph, IR_CONSTRAINT, "constrain_" + cname, cname)
  let g2 = fst(result)
  let nid = snd(result)
  let g3 = graph_add_edge(g2, nid, inner_id, EDGE_CONSTRAINS, cname)
  (IRBuilder { graph = g3 }, nid)

# evolve(inner, until) → IR_TEMPORAL 노드
function build_evolve(b: IRBuilder, inner_id: Int, until_tick: Int): (IRBuilder, Int) =
  let result = graph_add_node(b.graph, IR_TEMPORAL, "evolve_" + int_to_str(until_tick), int_to_str(until_tick))
  let g2 = fst(result)
  let nid = snd(result)
  let g3 = graph_add_edge(g2, inner_id, nid, EDGE_DEPENDS, "time_dep")
  (IRBuilder { graph = g3 }, nid)

# observe(inner) → IR_OBSERVE 노드
function build_observe(b: IRBuilder, inner_id: Int): (IRBuilder, Int) =
  let result = graph_add_node(b.graph, IR_OBSERVE, "observe", "")
  let g2 = fst(result)
  let nid = snd(result)
  let g3 = graph_add_edge(g2, inner_id, nid, EDGE_PRODUCES, "convergence")
  (IRBuilder { graph = g3 }, nid)

# compose(left, right) → IR_COMPOSE 노드 (left → compose ← right)
function build_compose(b: IRBuilder, left_id: Int, right_id: Int): (IRBuilder, Int) =
  let result = graph_add_node(b.graph, IR_COMPOSE, "compose", "")
  let g2 = fst(result)
  let nid = snd(result)
  let g3 = graph_add_edge(g2, left_id,  nid, EDGE_DEPENDS, "left")
  let g4 = graph_add_edge(g3, right_id, nid, EDGE_DEPENDS, "right")
  (IRBuilder { graph = g4 }, nid)

# ============================================================================
# IR 덤프 (디버깅)
# ============================================================================

function graph_dump(g: IRGraph): String =
  let header = "IRGraph [nodes=" + int_to_str(graph_node_count(g)) +
               " edges=" + int_to_str(graph_edge_count(g)) + "]\n"
  let node_str = dump_nodes(g.nodes, "")
  let edge_str = dump_edges(g.edges, "")
  header + node_str + edge_str

function dump_nodes(nodes: Array[IRNode], acc: String): String =
  if array_len(nodes) == 0 then acc
  else
    let n = array_head(nodes)
    let line = "  N" + int_to_str(n.id) + " [" + n.kind + "] " + n.label +
               (if n.payload != "" then " {" + n.payload + "}" else "") + "\n"
    dump_nodes(array_tail(nodes), acc + line)

function dump_edges(edges: Array[IREdge], acc: String): String =
  if array_len(edges) == 0 then acc
  else
    let e = array_head(edges)
    let line = "  N" + int_to_str(e.from) + " --[" + e.kind + "]--> N" +
               int_to_str(e.to) + " (" + e.label + ")\n"
    dump_edges(array_tail(edges), acc + line)

