# ============================================================================
# FVX Phase 1 — 테스트
# lexer.fl + ir/graph.fl 검증
# ============================================================================

# ============================================================================
# Lexer 테스트
# ============================================================================

function test_lex_fvx_keywords(): Bool =
  let tokens = tokenize("state consume constrain evolve observe compose")
  array_len(tokens) == 7 &&   # 6 키워드 + EOF
  (array_get(tokens, 0)).kind == TK_STATE &&
  (array_get(tokens, 1)).kind == TK_CONSUME &&
  (array_get(tokens, 2)).kind == TK_CONSTRAIN &&
  (array_get(tokens, 3)).kind == TK_EVOLVE &&
  (array_get(tokens, 4)).kind == TK_OBSERVE &&
  (array_get(tokens, 5)).kind == TK_COMPOSE

function test_lex_annotation(): Bool =
  let tokens = tokenize("@resource @pure @effect")
  array_len(tokens) == 4 &&
  (array_get(tokens, 0)).kind == TK_AT_RESOURCE &&
  (array_get(tokens, 1)).kind == TK_AT_PURE &&
  (array_get(tokens, 2)).kind == TK_AT_EFFECT

function test_lex_int_float(): Bool =
  let tokens = tokenize("42 3.14")
  (array_get(tokens, 0)).kind == TK_INT &&
  (array_get(tokens, 0)).lexeme == "42" &&
  (array_get(tokens, 1)).kind == TK_FLOAT &&
  (array_get(tokens, 1)).lexeme == "3.14"

function test_lex_string(): Bool =
  let tokens = tokenize("\"hello world\"")
  (array_get(tokens, 0)).kind == TK_STRING &&
  (array_get(tokens, 0)).lexeme == "hello world"

function test_lex_operators(): Bool =
  let tokens = tokenize("-> || | == != <= >=")
  (array_get(tokens, 0)).kind == TK_ARROW &&
  (array_get(tokens, 1)).kind == TK_PIPE2 &&
  (array_get(tokens, 2)).kind == TK_PIPE &&
  (array_get(tokens, 3)).kind == TK_EQ &&
  (array_get(tokens, 4)).kind == TK_NEQ &&
  (array_get(tokens, 5)).kind == TK_LE &&
  (array_get(tokens, 6)).kind == TK_GE

function test_lex_comment_skip(): Bool =
  let tokens = tokenize("state # 이건 주석\nconsume")
  array_len(tokens) == 4 &&   # state + NEWLINE + consume + EOF
  (array_get(tokens, 0)).kind == TK_STATE &&
  (array_get(tokens, 2)).kind == TK_CONSUME

function test_lex_types(): Bool =
  let tokens = tokenize("Int Float String Bool Any")
  (array_get(tokens, 0)).kind == TK_TYPE_INT &&
  (array_get(tokens, 1)).kind == TK_TYPE_FLOAT &&
  (array_get(tokens, 2)).kind == TK_TYPE_STR &&
  (array_get(tokens, 3)).kind == TK_TYPE_BOOL &&
  (array_get(tokens, 4)).kind == TK_TYPE_ANY

# FVX 프로그램 토크나이즈 (통합 테스트)
function test_lex_fvx_program(): Bool =
  let src = "observe(compose(state(1), constrain(state(2), \"type_eq\")))"
  let tokens = tokenize(src)
  # observe ( compose ( state ( 1 ) , constrain ( state ( 2 ) , "type_eq" ) ) ) EOF
  array_len(tokens) > 10 &&
  (array_get(tokens, 0)).kind == TK_OBSERVE &&
  (array_get(tokens, 1)).kind == TK_LPAREN &&
  (array_get(tokens, 2)).kind == TK_COMPOSE

# ============================================================================
# IR 그래프 테스트
# ============================================================================

function test_ir_state_node(): Bool =
  let b = new_builder()
  let result = build_state(b, 42)
  let b2 = fst(result)
  let nid = snd(result)
  let g = b2.graph
  graph_node_count(g) == 1 &&
  nid == 1 &&
  match graph_find_node(g, 1) {
    Some(n) => n.kind == IR_STATE && n.payload == "42"
    None    => false
  }

function test_ir_compose(): Bool =
  let b = new_builder()
  let r1 = build_state(b, 1)
  let b2 = fst(r1)
  let n1 = snd(r1)
  let r2 = build_state(b2, 2)
  let b3 = fst(r2)
  let n2 = snd(r2)
  let r3 = build_compose(b3, n1, n2)
  let b4 = fst(r3)
  let g  = b4.graph
  graph_node_count(g) == 3 &&
  graph_edge_count(g) == 2

function test_ir_constraint_flow(): Bool =
  let b = new_builder()
  let r1 = build_state(b, 10)
  let b2 = fst(r1)
  let s_id = snd(r1)
  let r2 = build_constrain(b2, s_id, "type_Int")
  let b3 = fst(r2)
  let g  = b3.graph
  # state 노드 + constraint 노드
  graph_node_count(g) == 2 &&
  graph_edge_count(g) == 1

function test_ir_full_pipeline(): Bool =
  # observe(consume(constrain(state(5), "Int"), 64, 10))
  let b  = new_builder()
  let r1 = build_state(b, 5)
  let b2 = fst(r1)
