# ============================================================================
# FVX — Parser (Phase 2)
# 승계: FreeJulia/src/parser.fl
#
# 변경사항:
#   - AST 노드: IntLiteral/BinaryOp/... → FVX 6개 코어 표현식 노드
#   - 문(Stmt) 제거 → 모든 것이 Expr (표현식 언어)
#   - parse_statement → parse_expr 단일 진입
#   - 파서 구조(Parser record, advance, expect, peek) 그대로 승계
#   - 파싱 결과를 IRBuilder 에 직접 연결
#
# 문법 (BNF):
#   program    ::= expr EOF
#   expr       ::= core_expr | let_bind | fn_decl | record_decl | annot_expr
#   core_expr  ::= state_expr | consume_expr | constrain_expr
#                | evolve_expr | observe_expr | compose_expr
#   state_expr ::= "state" "(" INT ")"
#   consume_expr ::= "consume" "(" expr "," resource_lit ")"
#   constrain_expr ::= "constrain" "(" expr "," STRING ")"
#   evolve_expr ::= "evolve" "(" expr "," INT ")"
#   observe_expr ::= "observe" "(" expr ")"
#   compose_expr ::= "compose" "(" expr "," expr ")"
#   let_bind   ::= "let" IDENT "=" expr
#   fn_decl    ::= "fn" IDENT "(" params ")" "->" type "=" expr
#   resource_lit ::= "{" "mem" "=" FLOAT "," "time" "=" FLOAT "}"
# ============================================================================

# ============================================================================
# Part 1: AST 노드
# ============================================================================

# 핵심 6개 표현식 노드
record ASTState {
  id: Int,
}

record ASTConsume {
  inner:  String,   # 직렬화 (재귀 AST 대신 심플하게)
  memory: Float,
  time_c: Float,
}

record ASTConstrain {
  inner: String,
  cname: String,
}

record ASTEvolve {
  inner:      String,
  until_tick: Int,
}

record ASTObserve {
  inner: String,
}

record ASTCompose {
  left:  String,
  right: String,
}

# 바인딩 & 선언
record ASTLet {
  name:  String,
  value: String,   # 직렬화된 RHS
}

record ASTFn {
  name:    String,
  params:  Array[(String, String)],   # (param_name, type_name)
  ret:     String,
  body:    String,
}

record ASTRecord {
  name:   String,
  fields: Array[(String, String)],    # (field_name, type_name)
}

record ASTAnnot {
  kind:  String,   # "resource" | "pure" | "effect"
  inner: String,
}

# 범용 AST 노드 (태그 기반)
record ASTNode {
  tag:     String,
  payload: String,
  line:    Int,
  col:     Int,
}

function ast_node(tag: String, payload: String, line: Int, col: Int): ASTNode =
  ASTNode { tag = tag, payload = payload, line = line, col = col }

# 파서 에러
record ParseError {
  msg:  String,
  line: Int,
  col:  Int,
}

function parse_error(msg: String, line: Int, col: Int): ParseError =
  ParseError { msg = msg, line = line, col = col }

# 파서 결과
record ParseResult {
  ok:    Bool,
  node:  ASTNode,
  error: ParseError,
}

function parse_ok(node: ASTNode): ParseResult =
  ParseResult {
    ok    = true,
    node  = node,
    error = ParseError { msg = "", line = 0, col = 0 },
  }

function parse_fail(msg: String, line: Int, col: Int): ParseResult =
  ParseResult {
    ok    = false,
    node  = ast_node("", "", 0, 0),
    error = parse_error(msg, line, col),
  }

# ============================================================================
# Part 2: Parser 구조체 (승계: FreeJulia Parser record)
# ============================================================================

record Parser {
  tokens:  Array[Token],
  pos:     Int,
  current: Token,
  errors:  Array[ParseError],
}

function new_parser(tokens: Array[Token]): Parser =
  let cur = if array_len(tokens) > 0 then array_get(tokens, 0)
            else new_token(TK_EOF, "", 0, 0)
  Parser {
    tokens  = tokens,
    pos     = 0,
    current = cur,
    errors  = [],
  }

# ============================================================================
# Part 3: 기본 메서드 (승계: FreeJulia advance_parser, expect_parser)
# ============================================================================

function advance(p: Parser): Parser =
  let next_pos = p.pos + 1
  let next_cur = if next_pos < array_len(p.tokens)
                 then array_get(p.tokens, next_pos)
                 else new_token(TK_EOF, "", 0, 0)
  Parser {
    tokens  = p.tokens,
    pos     = next_pos,
    current = next_cur,
    errors  = p.errors,
  }

function peek_at(p: Parser, offset: Int): Token =
  let idx = p.pos + offset
  if idx < array_len(p.tokens) then array_get(p.tokens, idx)
  else new_token(TK_EOF, "", 0, 0)

function expect(p: Parser, kind: String): (Parser, Token, Bool) =
  if p.current.kind == kind then
    (advance(p), p.current, true)
  else
    let err = parse_error(
      "예상: " + kind + ", 실제: " + p.current.kind + " (\"" + p.current.lexeme + "\")",
      p.current.line, p.current.col
    )
    let p2 = Parser {
      tokens  = p.tokens,
      pos     = p.pos,
      current = p.current,
      errors  = array_append(p.errors, err),
    }
    (p2, p.current, false)

function skip_newlines(p: Parser): Parser =
  if p.current.kind == TK_NEWLINE then skip_newlines(advance(p))
  else p

function is_binop(kind: String): Bool =
  kind == TK_PLUS || kind == TK_MINUS || kind == TK_STAR ||
  kind == TK_SLASH || kind == TK_EQ || kind == TK_NEQ ||
  kind == TK_LT || kind == TK_LE || kind == TK_GT || kind == TK_GE

function binop_prec(kind: String): Int =
  if kind == TK_EQ || kind == TK_NEQ then 1
  else if kind == TK_LT || kind == TK_LE || kind == TK_GT || kind == TK_GE then 2
  else if kind == TK_PLUS || kind == TK_MINUS then 3
  else if kind == TK_STAR || kind == TK_SLASH then 4
  else 0

# ============================================================================
# Part 4: 최상위 파싱 (승계: parse_program → FVX는 단일 expr)
# ============================================================================

record Program {
  nodes: Array[ASTNode],
}

function parse_program(input: String): (Program, Array[ParseError]) =
  let tokens = tokenize(input)
  let p = new_parser(tokens)
  let p2 = skip_newlines(p)
  parse_top(p2, [])

function parse_top(p: Parser, acc: Array[ASTNode]): (Program, Array[ParseError]) =
  let p2 = skip_newlines(p)
  if p2.current.kind == TK_EOF then
    (Program { nodes = acc }, p2.errors)
  else
    let result = parse_expr(p2)
    let p3 = fst(result)
    let pr  = snd(result)
    let p4  = skip_newlines(p3)
    if pr.ok then
      parse_top(p4, array_append(acc, pr.node))
    else
      # 에러 복구: 한 토큰 건너뜀
      let p5 = advance(p4)
      parse_top(p5, acc)

# ============================================================================
# Part 5: 표현식 파싱
# ============================================================================

function parse_expr(p: Parser): (Parser, ParseResult) =
  let kind = p.current.kind

  if kind == TK_STATE      then parse_state(p)
  else if kind == TK_CONSUME    then parse_consume(p)
  else if kind == TK_CONSTRAIN  then parse_constrain(p)
  else if kind == TK_EVOLVE     then parse_evolve(p)
  else if kind == TK_OBSERVE    then parse_observe(p)
  else if kind == TK_COMPOSE    then parse_compose(p)
  else if kind == TK_LET        then parse_let(p)
  else if kind == TK_FN         then parse_fn(p)
  else if kind == TK_RECORD     then parse_record(p)
  else if kind == TK_AT_RESOURCE || kind == TK_AT_PURE || kind == TK_AT_EFFECT
                                then parse_annot(p)
  else
    parse_atom(p)

# ============================================================================
# Part 6: state(INT)
# ============================================================================

function parse_state(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1   = advance(p)                         # 'state' 소비
  let r1   = expect(p1, TK_LPAREN)
  let p2   = fst3(r1)
  if snd3(r1) == false then
    (p2, parse_fail("state: '(' 예상", line, col))
  else
    let r2 = expect(p2, TK_INT)
    let p3 = fst3(r2)
    let id_tok = mid3(r2)
    if snd3(r2) == false then
      (p3, parse_fail("state: 정수 ID 예상", line, col))
    else
      let r3 = expect(p3, TK_RPAREN)
      let p4 = fst3(r3)
      let payload = id_tok.lexeme
      (p4, parse_ok(ast_node("state", payload, line, col)))

# ============================================================================
# Part 7: consume(expr, {mem=FLOAT, time=FLOAT})
# ============================================================================

function parse_consume(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)
  let r1 = expect(p1, TK_LPAREN)
  let p2 = fst3(r1)
  if snd3(r1) == false then
    (p2, parse_fail("consume: '(' 예상", line, col))
  else
    let inner_r = parse_expr(p2)
    let p3 = fst(inner_r)
    let inner_pr = snd(inner_r)
    if inner_pr.ok == false then (p3, inner_pr)
    else
      let r2 = expect(p3, TK_COMMA)
      let p4 = fst3(r2)
      # resource 리터럴: {mem=FLOAT,time=FLOAT} 또는 단순 FLOAT 2개
      let res_r = parse_resource_lit(p4)
      let p5    = fst(res_r)
      let mem   = fst(snd(res_r))
      let time_c = snd(snd(res_r))
      let r3 = expect(p5, TK_RPAREN)
      let p6 = fst3(r3)
      let payload = inner_pr.node.payload + "|" +
                    float_to_str(mem) + "," + float_to_str(time_c)
      (p6, parse_ok(ast_node("consume", payload, line, col)))

function parse_resource_lit(p: Parser): (Parser, (Float, Float)) =
  # {mem=FLOAT,time=FLOAT} 형태
  if p.current.kind == TK_LBRACE then
    let p1 = advance(p)   # {
    let p2 = skip_ident(p1)   # mem
    let p3 = skip_assign(p2)  # =
    let mem_r = read_float_tok(p3)
    let p4  = fst(mem_r)
    let mem = snd(mem_r)
    let p5  = skip_comma(p4)
    let p6  = skip_ident(p5)  # time
    let p7  = skip_assign(p6) # =
    let time_r = read_float_tok(p7)
    let p8   = fst(time_r)
    let time_c = snd(time_r)
    let p9 = if p8.current.kind == TK_RBRACE then advance(p8) else p8
    (p9, (mem, time_c))
  else
    # 단순: FLOAT , FLOAT
    let r1 = read_float_tok(p)
    let p1 = fst(r1)
    let mem = snd(r1)
    let p2 = skip_comma(p1)
    let r2 = read_float_tok(p2)
    (fst(r2), (mem, snd(r2)))

function skip_ident(p: Parser): Parser =
  if p.current.kind == TK_IDENT then advance(p) else p

function skip_assign(p: Parser): Parser =
  if p.current.kind == TK_ASSIGN then advance(p) else p

function skip_comma(p: Parser): Parser =
  if p.current.kind == TK_COMMA then advance(p) else p

function read_float_tok(p: Parser): (Parser, Float) =
  if p.current.kind == TK_FLOAT then
    (advance(p), str_to_float(p.current.lexeme))
  else if p.current.kind == TK_INT then
    (advance(p), int_to_float(str_to_int(p.current.lexeme)))
  else
    (p, 0.0)

# ============================================================================
# Part 8: constrain(expr, STRING)
# ============================================================================

function parse_constrain(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)
  let r1 = expect(p1, TK_LPAREN)
  let p2 = fst3(r1)
  if snd3(r1) == false then
    (p2, parse_fail("constrain: '(' 예상", line, col))
  else
    let inner_r = parse_expr(p2)
    let p3 = fst(inner_r)
    let inner_pr = snd(inner_r)
    if inner_pr.ok == false then (p3, inner_pr)
    else
      let r2 = expect(p3, TK_COMMA)
      let p4 = fst3(r2)
      let r3 = expect(p4, TK_STRING)
      let p5 = fst3(r3)
      let cname = mid3(r3).lexeme
      let r4 = expect(p5, TK_RPAREN)
      let p6 = fst3(r4)
      let payload = inner_pr.node.payload + "|" + cname
      (p6, parse_ok(ast_node("constrain", payload, line, col)))

# ============================================================================
# Part 9: evolve(expr, INT)
# ============================================================================

function parse_evolve(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)
  let r1 = expect(p1, TK_LPAREN)
  let p2 = fst3(r1)
  if snd3(r1) == false then
    (p2, parse_fail("evolve: '(' 예상", line, col))
  else
    let inner_r = parse_expr(p2)
    let p3 = fst(inner_r)
    let inner_pr = snd(inner_r)
    if inner_pr.ok == false then (p3, inner_pr)
    else
      let r2 = expect(p3, TK_COMMA)
      let p4 = fst3(r2)
      let r3 = expect(p4, TK_INT)
      let p5 = fst3(r3)
      let until = mid3(r3).lexeme
      let r4 = expect(p5, TK_RPAREN)
      let p6 = fst3(r4)
      let payload = inner_pr.node.payload + "|" + until
      (p6, parse_ok(ast_node("evolve", payload, line, col)))

# ============================================================================
# Part 10: observe(expr)
# ============================================================================

function parse_observe(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)
  let r1 = expect(p1, TK_LPAREN)
  let p2 = fst3(r1)
  if snd3(r1) == false then
    (p2, parse_fail("observe: '(' 예상", line, col))
  else
    let inner_r = parse_expr(p2)
    let p3 = fst(inner_r)
    let inner_pr = snd(inner_r)
    if inner_pr.ok == false then (p3, inner_pr)
    else
      let r2 = expect(p3, TK_RPAREN)
      let p4 = fst3(r2)
      (p4, parse_ok(ast_node("observe", inner_pr.node.tag + ":" + inner_pr.node.payload, line, col)))

# ============================================================================
# Part 11: compose(expr, expr)
# ============================================================================

function parse_compose(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)
  let r1 = expect(p1, TK_LPAREN)
  let p2 = fst3(r1)
  if snd3(r1) == false then
    (p2, parse_fail("compose: '(' 예상", line, col))
  else
    let left_r = parse_expr(p2)
    let p3 = fst(left_r)
    let left_pr = snd(left_r)
    if left_pr.ok == false then (p3, left_pr)
    else
      let r2 = expect(p3, TK_COMMA)
      let p4 = fst3(r2)
      let right_r = parse_expr(p4)
      let p5 = fst(right_r)
      let right_pr = snd(right_r)
      if right_pr.ok == false then (p5, right_pr)
      else
        let r3 = expect(p5, TK_RPAREN)
        let p6 = fst3(r3)
        let payload = left_pr.node.tag  + ":" + left_pr.node.payload +
                      "||" +
                      right_pr.node.tag + ":" + right_pr.node.payload
        (p6, parse_ok(ast_node("compose", payload, line, col)))

# ============================================================================
# Part 12: let IDENT = expr
# ============================================================================

function parse_let(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)   # 'let'
  let r1 = expect(p1, TK_IDENT)
  let p2 = fst3(r1)
  let name = mid3(r1).lexeme
  let r2 = expect(p2, TK_ASSIGN)
  let p3 = fst3(r2)
  let val_r = parse_expr(p3)
  let p4 = fst(val_r)
  let val_pr = snd(val_r)
  if val_pr.ok == false then (p4, val_pr)
  else
    let payload = name + "=" + val_pr.node.tag + ":" + val_pr.node.payload
    (p4, parse_ok(ast_node("let", payload, line, col)))

# ============================================================================
# Part 13: fn IDENT(params) -> type = expr
# ============================================================================

function parse_fn(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)   # 'fn'
  let r1 = expect(p1, TK_IDENT)
  let p2 = fst3(r1)
  let name = mid3(r1).lexeme
  let r2 = expect(p2, TK_LPAREN)
  let p3 = fst3(r2)
  let params_r = parse_params(p3, [])
  let p4 = fst(params_r)
  let params = snd(params_r)
  let r3 = expect(p4, TK_ARROW)
  let p5 = fst3(r3)
  let ret_r = parse_type_name(p5)
  let p6 = fst(ret_r)
  let ret = snd(ret_r)
  let r4 = expect(p6, TK_ASSIGN)
  let p7 = fst3(r4)
  let body_r = parse_expr(p7)
  let p8 = fst(body_r)
  let body_pr = snd(body_r)
  if body_pr.ok == false then (p8, body_pr)
  else
    let payload = name + "|" + params_to_str(params) + "|" + ret +
                  "|" + body_pr.node.tag + ":" + body_pr.node.payload
    (p8, parse_ok(ast_node("fn", payload, line, col)))

function parse_params(p: Parser, acc: Array[(String, String)]): (Parser, Array[(String, String)]) =
  if p.current.kind == TK_RPAREN then
    (advance(p), acc)
  else if p.current.kind == TK_IDENT then
    let name = p.current.lexeme
    let p1 = advance(p)
    let r1 = expect(p1, TK_COLON)
    let p2 = fst3(r1)
    let type_r = parse_type_name(p2)
    let p3 = fst(type_r)
    let type_name = snd(type_r)
    let p4 = if p3.current.kind == TK_COMMA then advance(p3) else p3
    parse_params(p4, array_append(acc, (name, type_name)))
  else
    (p, acc)

function parse_type_name(p: Parser): (Parser, String) =
  let kind = p.current.kind
  if kind == TK_TYPE_INT   then (advance(p), "Int")
  else if kind == TK_TYPE_FLOAT then (advance(p), "Float")
  else if kind == TK_TYPE_STR   then (advance(p), "String")
  else if kind == TK_TYPE_BOOL  then (advance(p), "Bool")
  else if kind == TK_TYPE_ANY   then (advance(p), "Any")
  else if kind == TK_IDENT      then (advance(p), p.current.lexeme)
  else (p, "Any")

function params_to_str(params: Array[(String, String)]): String =
  if array_len(params) == 0 then ""
  else
    let head = array_head(params)
    let rest = params_to_str(array_tail(params))
    fst(head) + ":" + snd(head) + (if rest != "" then "," + rest else "")

# ============================================================================
# Part 14: record NAME { fields }
# ============================================================================

function parse_record(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let p1 = advance(p)   # 'record'
  let r1 = expect(p1, TK_IDENT)
  let p2 = fst3(r1)
  let name = mid3(r1).lexeme
  let r2 = expect(p2, TK_LBRACE)
  let p3 = fst3(r2)
  let fields_r = parse_fields(p3, [])
  let p4 = fst(fields_r)
  let fields = snd(fields_r)
  let payload = name + "|" + params_to_str(fields)
  (p4, parse_ok(ast_node("record", payload, line, col)))

function parse_fields(p: Parser, acc: Array[(String, String)]): (Parser, Array[(String, String)]) =
  let p2 = skip_newlines(p)
  if p2.current.kind == TK_RBRACE then
    (advance(p2), acc)
  else if p2.current.kind == TK_IDENT then
    let name = p2.current.lexeme
    let p3 = advance(p2)
    let r1 = expect(p3, TK_COLON)
    let p4 = fst3(r1)
    let type_r = parse_type_name(p4)
    let p5 = fst(type_r)
    let type_name = snd(type_r)
    let p6 = skip_comma(skip_newlines(p5))
    parse_fields(p6, array_append(acc, (name, type_name)))
  else
    (p2, acc)

# ============================================================================
# Part 15: @annot expr
# ============================================================================

function parse_annot(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let annot_kind = if p.current.kind == TK_AT_RESOURCE then "resource"
                   else if p.current.kind == TK_AT_PURE then "pure"
                   else "effect"
  let p1 = advance(p)
  let inner_r = parse_expr(p1)
  let p2 = fst(inner_r)
  let inner_pr = snd(inner_r)
  if inner_pr.ok == false then (p2, inner_pr)
  else
    let payload = annot_kind + "|" + inner_pr.node.tag + ":" + inner_pr.node.payload
    (p2, parse_ok(ast_node("annot", payload, line, col)))

# ============================================================================
# Part 16: 원자 표현식 (INT, FLOAT, STRING, IDENT)
# ============================================================================

function parse_atom(p: Parser): (Parser, ParseResult) =
  let line = p.current.line
  let col  = p.current.col
  let kind = p.current.kind

  if kind == TK_INT then
    (advance(p), parse_ok(ast_node("int", p.current.lexeme, line, col)))
  else if kind == TK_FLOAT then
    (advance(p), parse_ok(ast_node("float", p.current.lexeme, line, col)))
  else if kind == TK_STRING then
    (advance(p), parse_ok(ast_node("string", p.current.lexeme, line, col)))
  else if kind == TK_TRUE then
    (advance(p), parse_ok(ast_node("bool", "true", line, col)))
  else if kind == TK_FALSE then
    (advance(p), parse_ok(ast_node("bool", "false", line, col)))
  else if kind == TK_IDENT then
    (advance(p), parse_ok(ast_node("ident", p.current.lexeme, line, col)))
  else if kind == TK_LPAREN then
    let p1 = advance(p)
    let r = parse_expr(p1)
    let p2 = fst(r)
    let pr = snd(r)
    let r2 = expect(p2, TK_RPAREN)
    (fst3(r2), pr)
  else
    (p, parse_fail("예상치 못한 토큰: " + p.current.kind + " (\"" + p.current.lexeme + "\")", line, col))

# ============================================================================
# 헬퍼: 3-tuple 접근
# ============================================================================

function fst3(t: (Parser, Token, Bool)): Parser = fst(fst_pair(t))
function mid3(t: (Parser, Token, Bool)): Token  = snd(fst_pair(t))  # 아래 재정의
function snd3(t: (Parser, Token, Bool)): Bool   = thd(t)

# FreeLang tuple 헬퍼 (3-tuple)
function fst_pair(t: (Parser, Token, Bool)): (Parser, Token) = (fst3_a(t), mid3_a(t))
function fst3_a(t: (Parser, Token, Bool)): Parser  = tuple3_first(t)
function mid3_a(t: (Parser, Token, Bool)): Token   = tuple3_second(t)
function thd(t: (Parser, Token, Bool)): Bool        = tuple3_third(t)

