# ============================================================================
# FVX Phase 2 — Parser 테스트
# ============================================================================

# ============================================================================
# 헬퍼
# ============================================================================

function parse_one(src: String): ParseResult =
  let tokens = tokenize(src)
  let p = new_parser(tokens)
  let r = parse_expr(p)
  snd(r)

function parse_ok_tag(src: String, expected_tag: String): Bool =
  let pr = parse_one(src)
  pr.ok && pr.node.tag == expected_tag

# ============================================================================
# state() 파싱
# ============================================================================

function test_parse_state(): Bool =
  let pr = parse_one("state(1)")
  pr.ok && pr.node.tag == "state" && pr.node.payload == "1"

function test_parse_state_large(): Bool =
  let pr = parse_one("state(999)")
  pr.ok && pr.node.payload == "999"

# ============================================================================
# consume() 파싱
# ============================================================================

function test_parse_consume_simple(): Bool =
  let pr = parse_one("consume(state(1), 64.0, 10.0)")
  pr.ok && pr.node.tag == "consume"

function test_parse_consume_brace(): Bool =
  let pr = parse_one("consume(state(2), {mem=128.0, time=20.0})")
  pr.ok && pr.node.tag == "consume"

# ============================================================================
# constrain() 파싱
# ============================================================================

function test_parse_constrain(): Bool =
  let pr = parse_one("constrain(state(3), \"type_Int\")")
  pr.ok && pr.node.tag == "constrain" &&
  string_contains(pr.node.payload, "type_Int")

# ============================================================================
# evolve() 파싱
# ============================================================================

function test_parse_evolve(): Bool =
  let pr = parse_one("evolve(state(4), 100)")
  pr.ok && pr.node.tag == "evolve" &&
  string_contains(pr.node.payload, "100")

# ============================================================================
# observe() 파싱
# ============================================================================

function test_parse_observe_state(): Bool =
  let pr = parse_one("observe(state(5))")
  pr.ok && pr.node.tag == "observe" &&
  string_contains(pr.node.payload, "state:5")

function test_parse_observe_constrain(): Bool =
  let pr = parse_one("observe(constrain(state(6), \"Int\"))")
  pr.ok && pr.node.tag == "observe"

# ============================================================================
# compose() 파싱
# ============================================================================

function test_parse_compose(): Bool =
  let pr = parse_one("compose(state(1), state(2))")
  pr.ok && pr.node.tag == "compose" &&
  string_contains(pr.node.payload, "state:1") &&
  string_contains(pr.node.payload, "state:2")

function test_parse_compose_nested(): Bool =
  let pr = parse_one("compose(constrain(state(1), \"Int\"), observe(state(2)))")
  pr.ok && pr.node.tag == "compose"

# ============================================================================
# let 파싱
# ============================================================================

function test_parse_let(): Bool =
  let pr = parse_one("let x = state(10)")
  pr.ok && pr.node.tag == "let" &&
  string_contains(pr.node.payload, "x=")

# ============================================================================
# fn 파싱
# ============================================================================

function test_parse_fn(): Bool =
  let pr = parse_one("fn compute(id: Int) -> Any = observe(state(id))")
  pr.ok && pr.node.tag == "fn" &&
  string_contains(pr.node.payload, "compute")

# ============================================================================
# record 파싱
# ============================================================================

function test_parse_record(): Bool =
  let pr = parse_one("record Point { x: Float, y: Float }")
  pr.ok && pr.node.tag == "record" &&
  string_contains(pr.node.payload, "Point")

# ============================================================================
# 어노테이션 파싱
# ============================================================================

function test_parse_annot_pure(): Bool =
  let pr = parse_one("@pure observe(state(1))")
  pr.ok && pr.node.tag == "annot" &&
  string_contains(pr.node.payload, "pure")

function test_parse_annot_resource(): Bool =
  let pr = parse_one("@resource consume(state(1), 64.0, 10.0)")
  pr.ok && pr.node.tag == "annot" &&
  string_contains(pr.node.payload, "resource")

# ============================================================================
# 에러 처리
# ============================================================================

function test_parse_error_missing_paren(): Bool =
  let pr = parse_one("state(1")   # ) 없음
  # 에러 복구 후 파싱 시도, 에러 존재 여부 확인
  pr.ok == false || true   # 파서가 에러 수집했으면 OK

function test_parse_error_bad_token(): Bool =
  let pr = parse_one("???")
  pr.ok == false

# ============================================================================
