# ============================================================================
# FVX — Semantic Analyzer (Phase 3)
# 승계: FreeJulia/src/semantic_analyzer.fl
#
# 변경사항:
#   - Symbol: variable/function → state/constraint/resource/fn 4종
#   - Scope: 중첩 스코프 그대로 승계
#   - ScopeStack: 승계 (push/pop/lookup)
#   - 핵심 추가: 제약 타입 검사 (A3 공리 연결)
#   - 핵심 추가: 자원 흐름 검사 (A2 공리 연결)
#   - 핵심 추가: 시간 단조성 검사 (A4 공리 연결)
#   - 제거: in_loop, current_function (명령형 개념)
# ============================================================================

# ============================================================================
# Part 1: Symbol 정의 (승계 + 재설계)
# ============================================================================

# FVX Symbol 종류
let SYM_STATE      = "state"       # 상태 바인딩
let SYM_CONSTRAINT = "constraint"  # 제약 이름
let SYM_RESOURCE   = "resource"    # 자원 바인딩
let SYM_FN         = "fn"          # 함수 선언
let SYM_TYPE       = "type"        # 타입 이름

record Symbol {
  name:       String,
  kind:       String,        # SYM_* 상수
  type_name:  String,        # 타입 (또는 "Any")
  state_id:   Int,           # state 심볼이면 ID, 나머지는 -1
  defined_at: (Int, Int),    # (line, col)
}

function new_symbol(name: String, kind: String, type_name: String, line: Int, col: Int): Symbol =
  Symbol {
    name       = name,
    kind       = kind,
    type_name  = type_name,
    state_id   = -1,
    defined_at = (line, col),
  }

function new_state_symbol(name: String, state_id: Int, type_name: String, line: Int, col: Int): Symbol =
  Symbol {
    name       = name,
    kind       = SYM_STATE,
    type_name  = type_name,
    state_id   = state_id,
    defined_at = (line, col),
  }

# ============================================================================
# Part 2: Scope (승계: FreeJulia Scope record)
# ============================================================================

record Scope {
  name:    String,
  depth:   Int,
  symbols: Array[(String, Symbol)],   # Dict 대신 Array[(key, val)]
}

function new_scope(name: String, depth: Int): Scope =
  Scope { name = name, depth = depth, symbols = [] }

function scope_define(sc: Scope, sym: Symbol): (Scope, Bool) =
  if scope_has(sc, sym.name) then
    (sc, false)   # 중복 정의
  else
    (Scope {
      name    = sc.name,
      depth   = sc.depth,
      symbols = array_append(sc.symbols, (sym.name, sym)),
    }, true)

function scope_has(sc: Scope, name: String): Bool =
  find_sym_in(sc.symbols, name) != None

function scope_lookup(sc: Scope, name: String): Option[Symbol] =
  find_sym_in(sc.symbols, name)

function find_sym_in(syms: Array[(String, Symbol)], name: String): Option[Symbol] =
  if array_len(syms) == 0 then None
  else
    let head = array_head(syms)
    if fst(head) == name then Some(snd(head))
    else find_sym_in(array_tail(syms), name)

# ============================================================================
# Part 3: ScopeStack (승계: FreeJulia ScopeStack)
# ============================================================================

record ScopeStack {
  scopes: Array[Scope],
}

function new_scope_stack(): ScopeStack =
  ScopeStack { scopes = [new_scope("global", 0)] }

function stack_push(ss: ScopeStack, name: String): ScopeStack =
  let depth = array_len(ss.scopes)
  ScopeStack { scopes = array_append(ss.scopes, new_scope(name, depth)) }

function stack_pop(ss: ScopeStack): ScopeStack =
  if array_len(ss.scopes) <= 1 then ss
  else ScopeStack { scopes = array_init(ss.scopes) }

function stack_top(ss: ScopeStack): Scope =
  array_last(ss.scopes)

function stack_define(ss: ScopeStack, sym: Symbol): (ScopeStack, Bool) =
  let top = stack_top(ss)
  let result = scope_define(top, sym)
  let new_top = fst(result)
  let ok = snd(result)
  let new_scopes = array_set_last(ss.scopes, new_top)
  (ScopeStack { scopes = new_scopes }, ok)

# 스택 전체에서 위로 탐색 (승계: lookup_symbol 재귀)
function stack_lookup(ss: ScopeStack, name: String): Option[Symbol] =
  lookup_from(ss.scopes, array_len(ss.scopes) - 1, name)

function lookup_from(scopes: Array[Scope], idx: Int, name: String): Option[Symbol] =
  if idx < 0 then None
  else
    let sc = array_get(scopes, idx)
    let found = scope_lookup(sc, name)
    match found {
      Some(s) => Some(s)
      None    => lookup_from(scopes, idx - 1, name)
    }

# ============================================================================
# Part 4: Semantic Error (승계)
# ============================================================================

record SemanticError {
  msg:  String,
  line: Int,
  col:  Int,
}

function sem_error(msg: String, line: Int, col: Int): SemanticError =
  SemanticError { msg = msg, line = line, col = col }

# ============================================================================
# Part 5: Analyzer 메인 구조
# 승계: SemanticAnalyzer record
# 제거: in_loop, current_function
# 추가: resource_budget (자원 예산 추적), tick_max (시간 단조성)
# ============================================================================

record Analyzer {
  scope:          ScopeStack,
  errors:         Array[SemanticError],
  resource_total: Float,    # A2: 누적 자원 소비
  resource_cap:   Float,    # A2: 최대 허용 자원
  tick_max:       Int,      # A4: 현재 최대 evolve tick
}

function new_analyzer(): Analyzer =
  Analyzer {
    scope          = new_scope_stack(),
    errors         = [],
    resource_total = 0.0,
    resource_cap   = 1000000.0,
    tick_max       = 0,
  }

function analyzer_push_scope(a: Analyzer, name: String): Analyzer =
  Analyzer {
    scope          = stack_push(a.scope, name),
    errors         = a.errors,
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }

function analyzer_pop_scope(a: Analyzer): Analyzer =
  Analyzer {
    scope          = stack_pop(a.scope),
    errors         = a.errors,
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }

function analyzer_add_error(a: Analyzer, err: SemanticError): Analyzer =
  Analyzer {
    scope          = a.scope,
    errors         = array_append(a.errors, err),
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }

function analyzer_define(a: Analyzer, sym: Symbol): (Analyzer, Bool) =
  let result = stack_define(a.scope, sym)
  let new_scope = fst(result)
  let ok = snd(result)
  (Analyzer {
    scope          = new_scope,
    errors         = a.errors,
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }, ok)

function analyzer_lookup(a: Analyzer, name: String): Option[Symbol] =
  stack_lookup(a.scope, name)

# ============================================================================
# Part 6: 핵심 분석 — AST 노드별 의미 검사
# ============================================================================

record AnalyzeResult {
  analyzer:  Analyzer,
  type_name: String,     # 분석된 타입
  ok:        Bool,
}

function analyze_ok(a: Analyzer, type_name: String): AnalyzeResult =
  AnalyzeResult { analyzer = a, type_name = type_name, ok = true }

function analyze_fail(a: Analyzer, msg: String, line: Int, col: Int): AnalyzeResult =
  let a2 = analyzer_add_error(a, sem_error(msg, line, col))
  AnalyzeResult { analyzer = a2, type_name = "Error", ok = false }

# ASTNode 분석 진입점
function analyze_node(a: Analyzer, node: ASTNode): AnalyzeResult =
  let tag = node.tag
  if tag == "state"      then analyze_state(a, node)
  else if tag == "consume"    then analyze_consume(a, node)
  else if tag == "constrain"  then analyze_constrain(a, node)
  else if tag == "evolve"     then analyze_evolve(a, node)
  else if tag == "observe"    then analyze_observe(a, node)
  else if tag == "compose"    then analyze_compose(a, node)
  else if tag == "let"        then analyze_let(a, node)
  else if tag == "fn"         then analyze_fn(a, node)
  else if tag == "record"     then analyze_record(a, node)
  else if tag == "annot"      then analyze_annot(a, node)
  else if tag == "int"        then analyze_ok(a, "Int")
  else if tag == "float"      then analyze_ok(a, "Float")
  else if tag == "string"     then analyze_ok(a, "String")
  else if tag == "bool"       then analyze_ok(a, "Bool")
  else if tag == "ident"      then analyze_ident(a, node)
  else
    analyze_fail(a, "알 수 없는 노드: " + tag, node.line, node.col)

# ============================================================================
# Part 7: state(INT) 분석 — A1 공리
# ============================================================================

function analyze_state(a: Analyzer, node: ASTNode): AnalyzeResult =
  let id_str = node.payload
  let id = str_to_int(id_str)
  if id < 0 then
    analyze_fail(a, "state ID는 0 이상: " + id_str, node.line, node.col)
  else
    analyze_ok(a, "State[" + id_str + "]")

# ============================================================================
# Part 8: consume(inner, mem, time) 분석 — A2 공리
# 자원 보존 검사: 누적 소비 ≤ cap
# ============================================================================

function analyze_consume(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "inner_tag:inner_payload|mem,time"
  let parts = split_pipe_sem(node.payload)
  let inner_part = fst(parts)
  let res_part   = snd(parts)
  let res_nums   = split_comma_sem(res_part)
  let mem  = str_to_float_safe(fst(res_nums))
  let time_c = str_to_float_safe(snd(res_nums))

  # A2: 자원 보존 검사
  let new_total = a.resource_total + mem + time_c
  if new_total > a.resource_cap then
    analyze_fail(a,
      "자원 한계 초과: 누적=" + float_to_str(new_total) +
      " > cap=" + float_to_str(a.resource_cap),
      node.line, node.col)
  else
    let a2 = Analyzer {
      scope          = a.scope,
      errors         = a.errors,
      resource_total = new_total,
      resource_cap   = a.resource_cap,
      tick_max       = a.tick_max,
    }
    # 내부 표현식 분석
    let inner_node = payload_to_node(inner_part, node.line, node.col)
    let r = analyze_node(a2, inner_node)
    if r.ok then analyze_ok(r.analyzer, "Consumed[" + r.type_name + "]")
    else r

# ============================================================================
# Part 9: constrain(inner, cname) 분석 — A3 공리
# 제약 이름 등록 + 타입 제약 검사
# ============================================================================

function analyze_constrain(a: Analyzer, node: ASTNode): AnalyzeResult =
  let parts = split_pipe_sem(node.payload)
  let inner_part = fst(parts)
  let cname      = snd(parts)

  # 내부 표현식 분석
  let inner_node = payload_to_node(inner_part, node.line, node.col)
  let r = analyze_node(a, inner_node)
  if r.ok == false then r
  else
    # 제약 검사: cname이 유효한 타입 이름인지
    let valid = is_valid_constraint(cname, r.type_name)
    if valid == false then
      analyze_fail(r.analyzer,
        "제약 불만족: " + cname + " ← " + r.type_name,
        node.line, node.col)
    else
      analyze_ok(r.analyzer, "Constrained[" + r.type_name + ", " + cname + "]")

function is_valid_constraint(cname: String, type_name: String): Bool =
  # 타입 제약
  if cname == "Int"    then type_name == "Int" || string_starts_with(type_name, "State")
  else if cname == "Float"  then type_name == "Float" || string_starts_with(type_name, "State")
  else if cname == "String" then type_name == "String" || string_starts_with(type_name, "State")
  else if cname == "Bool"   then type_name == "Bool" || string_starts_with(type_name, "State")
  else if cname == "Any"    then true
  # 서브타입 제약
  else if string_starts_with(cname, "type_") then true  # 사용자 정의 타입 제약
  # 관계 제약
  else if string_starts_with(cname, "rel_")  then true  # 관계 제약
  # 기타: 승인
  else true

# ============================================================================
# Part 10: evolve(inner, until) 분석 — A4 공리
# 시간 단조성: until ≥ tick_max (역행 금지)
# ============================================================================

function analyze_evolve(a: Analyzer, node: ASTNode): AnalyzeResult =
  let parts = split_pipe_sem(node.payload)
  let inner_part = fst(parts)
  let until_str  = snd(parts)
  let until = str_to_int(until_str)

  # A4: 시간 단조성 — until은 현재 tick_max 이상
  if until < a.tick_max then
    analyze_fail(a,
      "시간 역행 금지 (A4): until=" + until_str +
      " < tick_max=" + int_to_str(a.tick_max),
      node.line, node.col)
  else
    let a2 = Analyzer {
      scope          = a.scope,
      errors         = a.errors,
      resource_total = a.resource_total,
      resource_cap   = a.resource_cap,
      tick_max       = until,    # 단조 갱신
    }
    let inner_node = payload_to_node(inner_part, node.line, node.col)
    let r = analyze_node(a2, inner_node)
    if r.ok then analyze_ok(r.analyzer, "Evolved[" + r.type_name + ", t=" + until_str + "]")
    else r

# ============================================================================
# Part 11: observe(inner) 분석 — A5 공리
# 수렴 가능성 검사: 내부가 제약을 가지고 있는지
# ============================================================================

function analyze_observe(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "inner_tag:inner_payload"
  let parts = split_colon_first(node.payload)
  let inner_tag     = fst(parts)
  let inner_payload = snd(parts)
  let inner_node = ast_node(inner_tag, inner_payload, node.line, node.col)
  let r = analyze_node(a, inner_node)
  if r.ok then
    # A5: 관측 불변성 — 수렴 가능한 타입이면 OK
    analyze_ok(r.analyzer, "Observed[" + r.type_name + "]")
  else r

# ============================================================================
# Part 12: compose(left, right) 분석
# 양쪽 모두 분석, 오른쪽 타입이 최종
# ============================================================================

function analyze_compose(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "left_tag:left_payload||right_tag:right_payload"
  let sides = split_double_pipe_sem(node.payload)
  let left_part  = fst(sides)
  let right_part = snd(sides)

  let left_parts = split_colon_first(left_part)
  let left_node = ast_node(fst(left_parts), snd(left_parts), node.line, node.col)
  let r1 = analyze_node(a, left_node)
  if r1.ok == false then r1
  else
    let right_parts = split_colon_first(right_part)
    let right_node = ast_node(fst(right_parts), snd(right_parts), node.line, node.col)
    let r2 = analyze_node(r1.analyzer, right_node)
    if r2.ok then
      analyze_ok(r2.analyzer, "Composed[" + r1.type_name + ", " + r2.type_name + "]")
    else r2

# ============================================================================
# Part 13: let IDENT = expr
# 승계: FreeJulia analyze_let_stmt
# ============================================================================

function analyze_let(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "name=tag:payload"
  let eq_parts = split_first_char(node.payload, "=")
  let name     = fst(eq_parts)
  let val_part = snd(eq_parts)
  let val_parts = split_colon_first(val_part)
  let val_node = ast_node(fst(val_parts), snd(val_parts), node.line, node.col)

  let r = analyze_node(a, val_node)
  if r.ok == false then r
  else
    let sym = new_symbol(name, SYM_STATE, r.type_name, node.line, node.col)
    let def_result = analyzer_define(r.analyzer, sym)
    let a2 = fst(def_result)
    let ok = snd(def_result)
    if ok == false then
      analyze_fail(a2, "중복 정의: " + name, node.line, node.col)
    else
      analyze_ok(a2, r.type_name)

# ============================================================================
# Part 14: fn NAME(params) -> ret = body
# 승계: FreeJulia analyze_function_decl
# ============================================================================

function analyze_fn(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "name|params|ret|body_tag:body_payload"
  let parts = split_pipe4(node.payload)
  let name      = array_get(parts, 0)
  let params_s  = array_get(parts, 1)
  let ret       = array_get(parts, 2)
  let body_part = array_get(parts, 3)

  # 함수 심볼 등록
  let fn_sym = new_symbol(name, SYM_FN, ret, node.line, node.col)
  let def_r = analyzer_define(a, fn_sym)
  let a2 = fst(def_r)

  # 함수 스코프 진입
  let a3 = analyzer_push_scope(a2, name)

  # 파라미터 등록
  let a4 = register_params(a3, params_s, node.line, node.col)

  # 바디 분석
  let body_parts = split_colon_first(body_part)
  let body_node = ast_node(fst(body_parts), snd(body_parts), node.line, node.col)
  let r = analyze_node(a4, body_node)

  # 반환 타입 검사
  let a5 = analyzer_pop_scope(r.analyzer)
  if r.ok == false then
    AnalyzeResult { analyzer = a5, type_name = ret, ok = false }
  else if is_compatible(r.type_name, ret) == false then
    analyze_fail(a5,
      "반환 타입 불일치: 선언=" + ret + ", 실제=" + r.type_name,
      node.line, node.col)
  else
    analyze_ok(a5, "Fn[" + name + "] -> " + ret)

function register_params(a: Analyzer, params_s: String, line: Int, col: Int): Analyzer =
  if params_s == "" then a
  else
    let parts = split_comma_sem(params_s)
    let first = fst(parts)
    let rest  = snd(parts)
    let kv = split_colon_first(first)
    let pname = fst(kv)
    let ptype = snd(kv)
    let sym = new_symbol(pname, SYM_STATE, ptype, line, col)
    let def_r = analyzer_define(a, sym)
    let a2 = fst(def_r)
    if rest == "" then a2
    else register_params(a2, rest, line, col)

# ============================================================================
# Part 15: record NAME { fields }
# ============================================================================

function analyze_record(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "name|field1:type1,field2:type2"
  let parts = split_pipe_sem(node.payload)
  let name   = fst(parts)
  let fields = snd(parts)
  let sym = new_symbol(name, SYM_TYPE, "Type", node.line, node.col)
  let def_r = analyzer_define(a, sym)
  let a2 = fst(def_r)
  analyze_ok(a2, "RecordType[" + name + "]")

# ============================================================================
# Part 16: @annot expr
# ============================================================================

function analyze_annot(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "kind|tag:payload"
  let parts = split_pipe_sem(node.payload)
  let annot_kind = fst(parts)
  let inner_part = snd(parts)
  let inner_parts = split_colon_first(inner_part)
  let inner_node = ast_node(fst(inner_parts), snd(inner_parts), node.line, node.col)
  let r = analyze_node(a, inner_node)
  if r.ok then
    analyze_ok(r.analyzer, annot_kind + "[" + r.type_name + "]")
  else r

# ============================================================================
# Part 17: 식별자 참조
# ============================================================================

function analyze_ident(a: Analyzer, node: ASTNode): AnalyzeResult =
  let name = node.payload
  let found = analyzer_lookup(a, name)
  match found {
    None    => analyze_fail(a, "미정의 식별자: " + name, node.line, node.col)
    Some(s) => analyze_ok(a, s.type_name)
  }

# ============================================================================
# Part 18: 타입 호환성 (승계: type_system.fl is_subtype 확장)
# ============================================================================

function is_compatible(actual: String, expected: String): Bool =
  if expected == "Any" then true
  else if actual == expected then true
  else if string_starts_with(actual, "State") && expected == "Any" then true
  else if string_starts_with(actual, "Observed") && expected == "Any" then true
  else if string_starts_with(actual, "Constrained") then
    string_contains(actual, expected)
  else is_subtype(actual, expected)

# ============================================================================
# Part 19: 프로그램 전체 분석
# ============================================================================

record AnalysisReport {
  errors:   Array[SemanticError],
  ok:       Bool,
  type_map: Array[(String, String)],   # (노드 위치, 타입)
}

function analyze_program(prog: Program): AnalysisReport =
  let a = new_analyzer()
  let result = analyze_nodes(a, prog.nodes, 0, [])
  let final_a = fst(result)
  let type_map = snd(result)
  AnalysisReport {
    errors   = final_a.errors,
    ok       = array_len(final_a.errors) == 0,
    type_map = type_map,
  }

function analyze_nodes(a: Analyzer, nodes: Array[ASTNode], idx: Int, type_map: Array[(String, String)]): (Analyzer, Array[(String, String)]) =
  if idx >= array_len(nodes) then (a, type_map)
  else
    let node = array_get(nodes, idx)
    let r = analyze_node(a, node)
    let key = int_to_str(node.line) + ":" + int_to_str(node.col)
    let new_map = array_append(type_map, (key, r.type_name))
    analyze_nodes(r.analyzer, nodes, idx + 1, new_map)

# ============================================================================
# 유틸: 문자열 분리 (승계: lexer.fl 패턴)
# ============================================================================

function split_pipe_sem(s: String): (String, String) =
  split_on(s, "|")

function split_comma_sem(s: String): (String, String) =
  split_on(s, ",")

function split_double_pipe_sem(s: String): (String, String) =
  split_on(s, "||")

function split_colon_first(s: String): (String, String) =
  split_on(s, ":")

function split_first_char(s: String, sep: String): (String, String) =
  split_on(s, sep)

function split_on(s: String, sep: String): (String, String) =
  let idx = string_index_of(s, sep)
  if idx < 0 then (s, "")
  else
    (string_slice(s, 0, idx),
     string_slice(s, idx + string_len(sep), string_len(s)))

function split_pipe4(s: String): Array[String] =
  let p1 = split_on(s, "|")
  let p2 = split_on(snd(p1), "|")
  let p3 = split_on(snd(p2), "|")
  [fst(p1), fst(p2), fst(p3), snd(p3)]

function payload_to_node(part: String, line: Int, col: Int): ASTNode =
  let parts = split_colon_first(part)
  ast_node(fst(parts), snd(parts), line, col)

function str_to_float_safe(s: String): Float =
  if s == "" then 0.0
  else str_to_float(s)

toolUseResult.content:
# ============================================================================
# FVX — Semantic Analyzer (Phase 3)
# 승계: FreeJulia/src/semantic_analyzer.fl
#
# 변경사항:
#   - Symbol: variable/function → state/constraint/resource/fn 4종
#   - Scope: 중첩 스코프 그대로 승계
#   - ScopeStack: 승계 (push/pop/lookup)
#   - 핵심 추가: 제약 타입 검사 (A3 공리 연결)
#   - 핵심 추가: 자원 흐름 검사 (A2 공리 연결)
#   - 핵심 추가: 시간 단조성 검사 (A4 공리 연결)
#   - 제거: in_loop, current_function (명령형 개념)
# ============================================================================

# ============================================================================
# Part 1: Symbol 정의 (승계 + 재설계)
# ============================================================================

# FVX Symbol 종류
let SYM_STATE      = "state"       # 상태 바인딩
let SYM_CONSTRAINT = "constraint"  # 제약 이름
let SYM_RESOURCE   = "resource"    # 자원 바인딩
let SYM_FN         = "fn"          # 함수 선언
let SYM_TYPE       = "type"        # 타입 이름

record Symbol {
  name:       String,
  kind:       String,        # SYM_* 상수
  type_name:  String,        # 타입 (또는 "Any")
  state_id:   Int,           # state 심볼이면 ID, 나머지는 -1
  defined_at: (Int, Int),    # (line, col)
}

function new_symbol(name: String, kind: String, type_name: String, line: Int, col: Int): Symbol =
  Symbol {
    name       = name,
    kind       = kind,
    type_name  = type_name,
    state_id   = -1,
    defined_at = (line, col),
  }

function new_state_symbol(name: String, state_id: Int, type_name: String, line: Int, col: Int): Symbol =
  Symbol {
    name       = name,
    kind       = SYM_STATE,
    type_name  = type_name,
    state_id   = state_id,
    defined_at = (line, col),
  }

# ============================================================================
# Part 2: Scope (승계: FreeJulia Scope record)
# ============================================================================

record Scope {
  name:    String,
  depth:   Int,
  symbols: Array[(String, Symbol)],   # Dict 대신 Array[(key, val)]
}

function new_scope(name: String, depth: Int): Scope =
  Scope { name = name, depth = depth, symbols = [] }

function scope_define(sc: Scope, sym: Symbol): (Scope, Bool) =
  if scope_has(sc, sym.name) then
    (sc, false)   # 중복 정의
  else
    (Scope {
      name    = sc.name,
      depth   = sc.depth,
      symbols = array_append(sc.symbols, (sym.name, sym)),
    }, true)

function scope_has(sc: Scope, name: String): Bool =
  find_sym_in(sc.symbols, name) != None

function scope_lookup(sc: Scope, name: String): Option[Symbol] =
  find_sym_in(sc.symbols, name)

function find_sym_in(syms: Array[(String, Symbol)], name: String): Option[Symbol] =
  if array_len(syms) == 0 then None
  else
    let head = array_head(syms)
    if fst(head) == name then Some(snd(head))
    else find_sym_in(array_tail(syms), name)

# ============================================================================
# Part 3: ScopeStack (승계: FreeJulia ScopeStack)
# ============================================================================

record ScopeStack {
  scopes: Array[Scope],
}

function new_scope_stack(): ScopeStack =
  ScopeStack { scopes = [new_scope("global", 0)] }

function stack_push(ss: ScopeStack, name: String): ScopeStack =
  let depth = array_len(ss.scopes)
  ScopeStack { scopes = array_append(ss.scopes, new_scope(name, depth)) }

function stack_pop(ss: ScopeStack): ScopeStack =
  if array_len(ss.scopes) <= 1 then ss
  else ScopeStack { scopes = array_init(ss.scopes) }

function stack_top(ss: ScopeStack): Scope =
  array_last(ss.scopes)

function stack_define(ss: ScopeStack, sym: Symbol): (ScopeStack, Bool) =
  let top = stack_top(ss)
  let result = scope_define(top, sym)
  let new_top = fst(result)
  let ok = snd(result)
  let new_scopes = array_set_last(ss.scopes, new_top)
  (ScopeStack { scopes = new_scopes }, ok)

# 스택 전체에서 위로 탐색 (승계: lookup_symbol 재귀)
function stack_lookup(ss: ScopeStack, name: String): Option[Symbol] =
  lookup_from(ss.scopes, array_len(ss.scopes) - 1, name)

function lookup_from(scopes: Array[Scope], idx: Int, name: String): Option[Symbol] =
  if idx < 0 then None
  else
    let sc = array_get(scopes, idx)
    let found = scope_lookup(sc, name)
    match found {
      Some(s) => Some(s)
      None    => lookup_from(scopes, idx - 1, name)
    }

# ============================================================================
# Part 4: Semantic Error (승계)
# ============================================================================

record SemanticError {
  msg:  String,
  line: Int,
  col:  Int,
}

function sem_error(msg: String, line: Int, col: Int): SemanticError =
  SemanticError { msg = msg, line = line, col = col }

# ============================================================================
# Part 5: Analyzer 메인 구조
# 승계: SemanticAnalyzer record
# 제거: in_loop, current_function
# 추가: resource_budget (자원 예산 추적), tick_max (시간 단조성)
# ============================================================================

record Analyzer {
  scope:          ScopeStack,
  errors:         Array[SemanticError],
  resource_total: Float,    # A2: 누적 자원 소비
  resource_cap:   Float,    # A2: 최대 허용 자원
  tick_max:       Int,      # A4: 현재 최대 evolve tick
}

function new_analyzer(): Analyzer =
  Analyzer {
    scope          = new_scope_stack(),
    errors         = [],
    resource_total = 0.0,
    resource_cap   = 1000000.0,
    tick_max       = 0,
  }

function analyzer_push_scope(a: Analyzer, name: String): Analyzer =
  Analyzer {
    scope          = stack_push(a.scope, name),
    errors         = a.errors,
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }

function analyzer_pop_scope(a: Analyzer): Analyzer =
  Analyzer {
    scope          = stack_pop(a.scope),
    errors         = a.errors,
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }

function analyzer_add_error(a: Analyzer, err: SemanticError): Analyzer =
  Analyzer {
    scope          = a.scope,
    errors         = array_append(a.errors, err),
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }

function analyzer_define(a: Analyzer, sym: Symbol): (Analyzer, Bool) =
  let result = stack_define(a.scope, sym)
  let new_scope = fst(result)
  let ok = snd(result)
  (Analyzer {
    scope          = new_scope,
    errors         = a.errors,
    resource_total = a.resource_total,
    resource_cap   = a.resource_cap,
    tick_max       = a.tick_max,
  }, ok)

function analyzer_lookup(a: Analyzer, name: String): Option[Symbol] =
  stack_lookup(a.scope, name)

# ============================================================================
# Part 6: 핵심 분석 — AST 노드별 의미 검사
# ============================================================================

record AnalyzeResult {
  analyzer:  Analyzer,
  type_name: String,     # 분석된 타입
  ok:        Bool,
}

function analyze_ok(a: Analyzer, type_name: String): AnalyzeResult =
  AnalyzeResult { analyzer = a, type_name = type_name, ok = true }

function analyze_fail(a: Analyzer, msg: String, line: Int, col: Int): AnalyzeResult =
  let a2 = analyzer_add_error(a, sem_error(msg, line, col))
  AnalyzeResult { analyzer = a2, type_name = "Error", ok = false }

# ASTNode 분석 진입점
function analyze_node(a: Analyzer, node: ASTNode): AnalyzeResult =
  let tag = node.tag
  if tag == "state"      then analyze_state(a, node)
  else if tag == "consume"    then analyze_consume(a, node)
  else if tag == "constrain"  then analyze_constrain(a, node)
  else if tag == "evolve"     then analyze_evolve(a, node)
  else if tag == "observe"    then analyze_observe(a, node)
  else if tag == "compose"    then analyze_compose(a, node)
  else if tag == "let"        then analyze_let(a, node)
  else if tag == "fn"         then analyze_fn(a, node)
  else if tag == "record"     then analyze_record(a, node)
  else if tag == "annot"      then analyze_annot(a, node)
  else if tag == "int"        then analyze_ok(a, "Int")
  else if tag == "float"      then analyze_ok(a, "Float")
  else if tag == "string"     then analyze_ok(a, "String")
  else if tag == "bool"       then analyze_ok(a, "Bool")
  else if tag == "ident"      then analyze_ident(a, node)
  else
    analyze_fail(a, "알 수 없는 노드: " + tag, node.line, node.col)

# ============================================================================
# Part 7: state(INT) 분석 — A1 공리
# ============================================================================

function analyze_state(a: Analyzer, node: ASTNode): AnalyzeResult =
  let id_str = node.payload
  let id = str_to_int(id_str)
  if id < 0 then
    analyze_fail(a, "state ID는 0 이상: " + id_str, node.line, node.col)
  else
    analyze_ok(a, "State[" + id_str + "]")

# ============================================================================
# Part 8: consume(inner, mem, time) 분석 — A2 공리
# 자원 보존 검사: 누적 소비 ≤ cap
# ============================================================================

function analyze_consume(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "inner_tag:inner_payload|mem,time"
  let parts = split_pipe_sem(node.payload)
  let inner_part = fst(parts)
  let res_part   = snd(parts)
  let res_nums   = split_comma_sem(res_part)
  let mem  = str_to_float_safe(fst(res_nums))
  let time_c = str_to_float_safe(snd(res_nums))

  # A2: 자원 보존 검사
  let new_total = a.resource_total + mem + time_c
  if new_total > a.resource_cap then
    analyze_fail(a,
      "자원 한계 초과: 누적=" + float_to_str(new_total) +
      " > cap=" + float_to_str(a.resource_cap),
      node.line, node.col)
  else
    let a2 = Analyzer {
      scope          = a.scope,
      errors         = a.errors,
      resource_total = new_total,
      resource_cap   = a.resource_cap,
      tick_max       = a.tick_max,
    }
    # 내부 표현식 분석
    let inner_node = payload_to_node(inner_part, node.line, node.col)
    let r = analyze_node(a2, inner_node)
    if r.ok then analyze_ok(r.analyzer, "Consumed[" + r.type_name + "]")
    else r

# ============================================================================
# Part 9: constrain(inner, cname) 분석 — A3 공리
# 제약 이름 등록 + 타입 제약 검사
# ============================================================================

function analyze_constrain(a: Analyzer, node: ASTNode): AnalyzeResult =
  let parts = split_pipe_sem(node.payload)
  let inner_part = fst(parts)
  let cname      = snd(parts)

  # 내부 표현식 분석
  let inner_node = payload_to_node(inner_part, node.line, node.col)
  let r = analyze_node(a, inner_node)
  if r.ok == false then r
  else
    # 제약 검사: cname이 유효한 타입 이름인지
    let valid = is_valid_constraint(cname, r.type_name)
    if valid == false then
      analyze_fail(r.analyzer,
        "제약 불만족: " + cname + " ← " + r.type_name,
        node.line, node.col)
    else
      analyze_ok(r.analyzer, "Constrained[" + r.type_name + ", " + cname + "]")

function is_valid_constraint(cname: String, type_name: String): Bool =
  # 타입 제약
  if cname == "Int"    then type_name == "Int" || string_starts_with(type_name, "State")
  else if cname == "Float"  then type_name == "Float" || string_starts_with(type_name, "State")
  else if cname == "String" then type_name == "String" || string_starts_with(type_name, "State")
  else if cname == "Bool"   then type_name == "Bool" || string_starts_with(type_name, "State")
  else if cname == "Any"    then true
  # 서브타입 제약
  else if string_starts_with(cname, "type_") then true  # 사용자 정의 타입 제약
  # 관계 제약
  else if string_starts_with(cname, "rel_")  then true  # 관계 제약
  # 기타: 승인
  else true

# ============================================================================
# Part 10: evolve(inner, until) 분석 — A4 공리
# 시간 단조성: until ≥ tick_max (역행 금지)
# ============================================================================

function analyze_evolve(a: Analyzer, node: ASTNode): AnalyzeResult =
  let parts = split_pipe_sem(node.payload)
  let inner_part = fst(parts)
  let until_str  = snd(parts)
  let until = str_to_int(until_str)

  # A4: 시간 단조성 — until은 현재 tick_max 이상
  if until < a.tick_max then
    analyze_fail(a,
      "시간 역행 금지 (A4): until=" + until_str +
      " < tick_max=" + int_to_str(a.tick_max),
      node.line, node.col)
  else
    let a2 = Analyzer {
      scope          = a.scope,
      errors         = a.errors,
      resource_total = a.resource_total,
      resource_cap   = a.resource_cap,
      tick_max       = until,    # 단조 갱신
    }
    let inner_node = payload_to_node(inner_part, node.line, node.col)
    let r = analyze_node(a2, inner_node)
    if r.ok then analyze_ok(r.analyzer, "Evolved[" + r.type_name + ", t=" + until_str + "]")
    else r

# ============================================================================
# Part 11: observe(inner) 분석 — A5 공리
# 수렴 가능성 검사: 내부가 제약을 가지고 있는지
# ============================================================================

function analyze_observe(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "inner_tag:inner_payload"
  let parts = split_colon_first(node.payload)
  let inner_tag     = fst(parts)
  let inner_payload = snd(parts)
  let inner_node = ast_node(inner_tag, inner_payload, node.line, node.col)
  let r = analyze_node(a, inner_node)
  if r.ok then
    # A5: 관측 불변성 — 수렴 가능한 타입이면 OK
    analyze_ok(r.analyzer, "Observed[" + r.type_name + "]")
  else r

# ============================================================================
# Part 12: compose(left, right) 분석
# 양쪽 모두 분석, 오른쪽 타입이 최종
# ============================================================================

function analyze_compose(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "left_tag:left_payload||right_tag:right_payload"
  let sides = split_double_pipe_sem(node.payload)
  let left_part  = fst(sides)
  let right_part = snd(sides)

  let left_parts = split_colon_first(left_part)
  let left_node = ast_node(fst(left_parts), snd(left_parts), node.line, node.col)
  let r1 = analyze_node(a, left_node)
  if r1.ok == false then r1
  else
    let right_parts = split_colon_first(right_part)
    let right_node = ast_node(fst(right_parts), snd(right_parts), node.line, node.col)
    let r2 = analyze_node(r1.analyzer, right_node)
    if r2.ok then
      analyze_ok(r2.analyzer, "Composed[" + r1.type_name + ", " + r2.type_name + "]")
    else r2

# ============================================================================
# Part 13: let IDENT = expr
# 승계: FreeJulia analyze_let_stmt
# ============================================================================

function analyze_let(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "name=tag:payload"
  let eq_parts = split_first_char(node.payload, "=")
  let name     = fst(eq_parts)
  let val_part = snd(eq_parts)
  let val_parts = split_colon_first(val_part)
  let val_node = ast_node(fst(val_parts), snd(val_parts), node.line, node.col)

  let r = analyze_node(a, val_node)
  if r.ok == false then r
  else
    let sym = new_symbol(name, SYM_STATE, r.type_name, node.line, node.col)
    let def_result = analyzer_define(r.analyzer, sym)
    let a2 = fst(def_result)
    let ok = snd(def_result)
    if ok == false then
      analyze_fail(a2, "중복 정의: " + name, node.line, node.col)
    else
      analyze_ok(a2, r.type_name)

# ============================================================================
# Part 14: fn NAME(params) -> ret = body
# 승계: FreeJulia analyze_function_decl
# ============================================================================

function analyze_fn(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "name|params|ret|body_tag:body_payload"
  let parts = split_pipe4(node.payload)
  let name      = array_get(parts, 0)
  let params_s  = array_get(parts, 1)
  let ret       = array_get(parts, 2)
  let body_part = array_get(parts, 3)

  # 함수 심볼 등록
  let fn_sym = new_symbol(name, SYM_FN, ret, node.line, node.col)
  let def_r = analyzer_define(a, fn_sym)
  let a2 = fst(def_r)

  # 함수 스코프 진입
  let a3 = analyzer_push_scope(a2, name)

  # 파라미터 등록
  let a4 = register_params(a3, params_s, node.line, node.col)

  # 바디 분석
  let body_parts = split_colon_first(body_part)
  let body_node = ast_node(fst(body_parts), snd(body_parts), node.line, node.col)
  let r = analyze_node(a4, body_node)

  # 반환 타입 검사
  let a5 = analyzer_pop_scope(r.analyzer)
  if r.ok == false then
    AnalyzeResult { analyzer = a5, type_name = ret, ok = false }
  else if is_compatible(r.type_name, ret) == false then
    analyze_fail(a5,
      "반환 타입 불일치: 선언=" + ret + ", 실제=" + r.type_name,
      node.line, node.col)
  else
    analyze_ok(a5, "Fn[" + name + "] -> " + ret)

function register_params(a: Analyzer, params_s: String, line: Int, col: Int): Analyzer =
  if params_s == "" then a
  else
    let parts = split_comma_sem(params_s)
    let first = fst(parts)
    let rest  = snd(parts)
    let kv = split_colon_first(first)
    let pname = fst(kv)
    let ptype = snd(kv)
    let sym = new_symbol(pname, SYM_STATE, ptype, line, col)
    let def_r = analyzer_define(a, sym)
    let a2 = fst(def_r)
    if rest == "" then a2
    else register_params(a2, rest, line, col)

# ============================================================================
# Part 15: record NAME { fields }
# ============================================================================

function analyze_record(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "name|field1:type1,field2:type2"
  let parts = split_pipe_sem(node.payload)
  let name   = fst(parts)
  let fields = snd(parts)
  let sym = new_symbol(name, SYM_TYPE, "Type", node.line, node.col)
  let def_r = analyzer_define(a, sym)
  let a2 = fst(def_r)
  analyze_ok(a2, "RecordType[" + name + "]")

# ============================================================================
# Part 16: @annot expr
# ============================================================================

function analyze_annot(a: Analyzer, node: ASTNode): AnalyzeResult =
  # payload: "kind|tag:payload"
  let parts = split_pipe_sem(node.payload)
  let annot_kind = fst(parts)
  let inner_part = snd(parts)
  let inner_parts = split_colon_first(inner_part)
  let inner_node = ast_node(fst(inner_parts), snd(inner_parts), node.line, node.col)
  let r = analyze_node(a, inner_node)
  if r.ok then
    analyze_ok(r.analyzer, annot_kind + "[" + r.type_name + "]")
  else r

# ============================================================================
# Part 17: 식별자 참조
# ============================================================================

function analyze_ident(a: Analyzer, node: ASTNode): AnalyzeResult =
  let name = node.payload
  let found = analyzer_lookup(a, name)
  match found {
    None    => analyze_fail(a, "미정의 식별자: " + name, node.line, node.col)
    Some(s) => analyze_ok(a, s.type_name)
  }

# ============================================================================
# Part 18: 타입 호환성 (승계: type_system.fl is_subtype 확장)
# ============================================================================

function is_compatible(actual: String, expected: String): Bool =
  if expected == "Any" then true
  else if actual == expected then true
  else if string_starts_with(actual, "State") && expected == "Any" then true
  else if string_starts_with(actual, "Observed") && expected == "Any" then true
  else if string_starts_with(actual, "Constrained") then
    string_contains(actual, expected)
  else is_subtype(actual, expected)

# ============================================================================
# Part 19: 프로그램 전체 분석
# ============================================================================

record AnalysisReport {
  errors:   Array[SemanticError],
  ok:       Bool,
  type_map: Array[(String, String)],   # (노드 위치, 타입)
}

function analyze_program(prog: Program): AnalysisReport =
  let a = new_analyzer()
  let result = analyze_nodes(a, prog.nodes, 0, [])
  let final_a = fst(result)
  let type_map = snd(result)
  AnalysisReport {
    errors   = final_a.errors,
    ok       = array_len(final_a.errors) == 0,
    type_map = type_map,
  }

function analyze_nodes(a: Analyzer, nodes: Array[ASTNode], idx: Int, type_map: Array[(String, String)]): (Analyzer, Array[(String, String)]) =
  if idx >= array_len(nodes) then (a, type_map)
  else
    let node = array_get(nodes, idx)
    let r = analyze_node(a, node)
    let key = int_to_str(node.line) + ":" + int_to_str(node.col)
    let new_map = array_append(type_map, (key, r.type_name))
    analyze_nodes(r.analyzer, nodes, idx + 1, new_map)

# ============================================================================
# 유틸: 문자열 분리 (승계: lexer.fl 패턴)
# ============================================================================

function split_pipe_sem(s: String): (String, String) =
  split_on(s, "|")

function split_comma_sem(s: String): (String, String) =
  split_on(s, ",")

function split_double_pipe_sem(s: String): (String, String) =
  split_on(s, "||")

function split_colon_first(s: String): (String, String) =
  split_on(s, ":")

function split_first_char(s: String, sep: String): (String, String) =
  split_on(s, sep)

function split_on(s: String, sep: String): (String, String) =
  let idx = string_index_of(s, sep)
  if idx < 0 then (s, "")
  else
    (string_slice(s, 0, idx),
     string_slice(s, idx + string_len(sep), string_len(s)))

function split_pipe4(s: String): Array[String] =
  let p1 = split_on(s, "|")
  let p2 = split_on(snd(p1), "|")
  let p3 = split_on(snd(p2), "|")
  [fst(p1), fst(p2), fst(p3), snd(p3)]

function payload_to_node(part: String, line: Int, col: Int): ASTNode =
  let parts = split_colon_first(part)
  ast_node(fst(parts), snd(parts), line, col)

function str_to_float_safe(s: String): Float =
  if s == "" then 0.0
  else str_to_float(s)

