# ============================================================================
# FVX Phase 3 — Semantic Analyzer 테스트
# ============================================================================

# ============================================================================
# 헬퍼
# ============================================================================

function analyze_src(src: String): AnalysisReport =
  let r = parse_program(src)
  analyze_program(fst(r))

function assert_ok(src: String): Bool =
  let report = analyze_src(src)
  report.ok

function assert_fail(src: String): Bool =
  let report = analyze_src(src)
  report.ok == false

function assert_type(src: String, expected: String): Bool =
  let report = analyze_src(src)
  report.ok && array_len(report.type_map) > 0 &&
  string_contains(snd(array_last(report.type_map)), expected)

# ============================================================================
# A1: state 분석
# ============================================================================

function test_sem_state_valid(): Bool =
  assert_ok("state(1)")

function test_sem_state_type(): Bool =
  assert_type("state(42)", "State[42]")

# ============================================================================
# A2: consume 자원 보존
# ============================================================================

function test_sem_consume_ok(): Bool =
  assert_ok("consume(state(1), 100.0, 50.0)")

function test_sem_consume_type(): Bool =
  assert_type("consume(state(1), 10.0, 5.0)", "Consumed")

# ============================================================================
# A3: constrain 타입 검사
# ============================================================================

function test_sem_constrain_any(): Bool =
  assert_ok("constrain(state(1), \"Any\")")

function test_sem_constrain_type(): Bool =
  assert_type("constrain(state(1), \"Int\")", "Constrained")

function test_sem_constrain_custom(): Bool =
  assert_ok("constrain(state(1), \"type_mytype\")")

# ============================================================================
# A4: evolve 시간 단조성
# ============================================================================

function test_sem_evolve_ok(): Bool =
  assert_ok("evolve(state(1), 100)")

function test_sem_evolve_type(): Bool =
  assert_type("evolve(state(1), 50)", "Evolved")

function test_sem_evolve_monotone_fail(): Bool =
  # 두 evolve가 있는데 두 번째가 더 작은 tick → A4 위반
  let src = "evolve(evolve(state(1), 100), 50)"
  assert_fail(src)

# ============================================================================
# A5: observe
# ============================================================================

function test_sem_observe_state(): Bool =
  assert_type("observe(state(5))", "Observed")

function test_sem_observe_constrain(): Bool =
  assert_type("observe(constrain(state(1), \"Int\"))", "Observed")

function test_sem_observe_compose(): Bool =
  assert_type("observe(compose(state(1), state(2)))", "Observed")

# ============================================================================
# compose
# ============================================================================

function test_sem_compose_ok(): Bool =
  assert_ok("compose(state(1), state(2))")

function test_sem_compose_type(): Bool =
  assert_type("compose(state(1), state(2))", "Composed")

function test_sem_compose_nested(): Bool =
  assert_ok("compose(constrain(state(1), \"Any\"), observe(state(2)))")

# ============================================================================
# let 바인딩
# ============================================================================

function test_sem_let_ok(): Bool =
  assert_ok("let x = state(10)")

function test_sem_let_scope(): Bool =
  # let 후 ident 참조
  let src = "let x = state(1)"
  let r = parse_program(src)
  let prog = fst(r)
  let report = analyze_program(prog)
  report.ok &&
  match stack_lookup((new_analyzer()).scope, "x") {
    Some(_) => false   # 전역 아님 (다른 analyzer 인스턴스)
    None    => true
  }

function test_sem_let_duplicate_fail(): Bool =
  # 같은 이름 두 번 정의 → 실패
  let src = "let x = state(1)\nlet x = state(2)"
  assert_fail(src)

# ============================================================================
# fn 선언
# ============================================================================

function test_sem_fn_ok(): Bool =
  assert_ok("fn id(x: Int) -> Any = observe(state(1))")

function test_sem_fn_type(): Bool =
  assert_type("fn compute(n: Int) -> Any = observe(state(1))", "Fn[compute]")

# ============================================================================
# record 선언
# ============================================================================

function test_sem_record_ok(): Bool =
  assert_ok("record Point { x: Float, y: Float }")

function test_sem_record_type(): Bool =
  assert_type("record Vec { len: Int }", "RecordType[Vec]")

# ============================================================================
# 어노테이션
# ============================================================================

function test_sem_annot_pure(): Bool =
  assert_type("@pure observe(state(1))", "pure[Observed")

function test_sem_annot_resource(): Bool =
  assert_ok("@resource consume(state(1), 10.0, 5.0)")

# ============================================================================
# 통합: 전체 프로그램
# ============================================================================

function test_sem_full_program(): Bool =
  let src = "let s = state(1)\nlet c = constrain(s, \"Any\")\nobserve(c)"
  let report = analyze_src(src)
  report.ok && array_len(report.type_map) == 3

function test_sem_pipeline(): Bool =
  let src = "observe(compose(constrain(state(1), \"Int\"), consume(state(2), 64.0, 10.0)))"
  assert_ok(src)

# ============================================================================
# 실행
# ============================================================================

function run_phase3_tests(): Int =
  let results = [
    ("A1: state 유효",               test_sem_state_valid()),
    ("A1: state 타입",               test_sem_state_type()),
    ("A2: consume OK",               test_sem_consume_ok()),
    ("A2: consume 타입",             test_sem_consume_type()),
    ("A3: constrain Any",            test_sem_constrain_any()),
    ("A3: constrain 타입",           test_sem_constrain_type()),
    ("A3: constrain 사용자정의",     test_sem_constrain_custom()),
    ("A4: evolve OK",                test_sem_evolve_ok()),
    ("A4: evolve 타입",              test_sem_evolve_type()),
    ("A4: 시간 역행 실패",           test_sem_evolve_monotone_fail()),
    ("A5: observe state",            test_sem_observe_state()),
    ("A5: observe constrain",        test_sem_observe_constrain()),
    ("A5: observe compose",          test_sem_observe_compose()),
    ("compose OK",                   test_sem_compose_ok()),
    ("compose 타입",                 test_sem_compose_type()),
    ("compose 중첩",                 test_sem_compose_nested()),
    ("let 바인딩",                   test_sem_let_ok()),
    ("let 스코프",                   test_sem_let_scope()),
    ("let 중복 실패",                test_sem_let_duplicate_fail()),
    ("fn 선언",                      test_sem_fn_ok()),
    ("fn 타입",                      test_sem_fn_type()),
    ("record 선언",                  test_sem_record_ok()),
    ("record 타입",                  test_sem_record_type()),
    ("@pure 어노테이션",             test_sem_annot_pure()),
    ("@resource 어노테이션",         test_sem_annot_resource()),
    ("통합: 전체 프로그램",          test_sem_full_program()),
    ("통합: 파이프라인",             test_sem_pipeline()),
  ]
  count_results(results, 0, 0)

function count_results(results: Array[(String, Bool)], pass: Int, idx: Int): Int =
  if idx >= array_len(results) then
    let _ = print("=== Phase 3 결과: " + int_to_str(pass) + "/" + int_to_str(array_len(results)) + " PASS ===")
    pass
  else
    let item = array_get(results, idx)
    let name = fst(item)
    let ok   = snd(item)
    let _ = if ok then print("[PASS] " + name)
            else print("[FAIL] " + name)
    count_results(results, if ok then pass + 1 else pass, idx + 1)

let passed = run_phase3_tests()

