# ============================================================================
# FVX — Pipeline (Phase 4)
# 소스 → Lexer → Parser → Semantic → IRBuilder → Solver
#
# 이것이 FVX의 "컴파일러"다.
# 단, "실행"이 없다. 수렴(Convergence)만 있다.
# ============================================================================

# ============================================================================
# Part 1: 파이프라인 단계 결과
# ============================================================================

record LexResult {
  ok:     Bool,
  tokens: Array[Token],
  error:  String,
}

record ParseResult2 {
  ok:     Bool,
  prog:   Program,
  errors: Array[ParseError],
}

record SemResult {
  ok:     Bool,
  report: AnalysisReport,
}

record IRResult {
  ok:    Bool,
  graph: IRGraph,
  root:  Int,       # 루트 노드 ID (-1이면 없음)
  error: String,
}

record PipelineResult {
  ok:          Bool,

  # 각 단계 결과
  lex:         LexResult,
  parse:       ParseResult2,
  sem:         SemResult,
  ir:          IRResult,
  solve:       SolveResult,

  # 최종
  converged_state: Int,    # 수렴한 상태 ID (-1이면 실패)
  total_steps:     Int,
}

function pipeline_ok(lex: LexResult, parse: ParseResult2, sem: SemResult, ir: IRResult, solve: SolveResult): PipelineResult =
  PipelineResult {
    ok              = true,
    lex             = lex,
    parse           = parse,
    sem             = sem,
    ir              = ir,
    solve           = solve,
    converged_state = solve.state_id,
    total_steps     = solve.steps,
  }

function pipeline_fail(lex: LexResult, parse: ParseResult2, sem: SemResult, ir: IRResult, solve: SolveResult, msg: String): PipelineResult =
  PipelineResult {
    ok              = false,
    lex             = lex,
    parse           = parse,
    sem             = sem,
    ir              = ir,
    solve           = SolveResult { ok = false, state_id = -1, steps = 0, error = msg },
    converged_state = -1,
    total_steps     = 0,
  }

# ============================================================================
# Part 2: 단계별 실행
# ============================================================================

# Step 1: Lex
function run_lex(src: String): LexResult =
  let tokens = tokenize(src)
  if array_len(tokens) == 0 then
    LexResult { ok = false, tokens = [], error = "빈 입력" }
  else
    LexResult { ok = true, tokens = tokens, error = "" }

# Step 2: Parse
function run_parse(lex: LexResult): ParseResult2 =
  if lex.ok == false then
    ParseResult2 {
      ok     = false,
      prog   = Program { nodes = [] },
      errors = [ParseError { msg = lex.error, line = 0, col = 0 }],
    }
  else
    let p = new_parser(lex.tokens)
    let p2 = skip_newlines(p)
    let r = parse_top(p2, [])
    let prog = fst(r)
    let errs = snd(r)
    ParseResult2 {
      ok     = array_len(errs) == 0,
      prog   = prog,
      errors = errs,
    }

# Step 3: Semantic
function run_sem(parse: ParseResult2): SemResult =
  if parse.ok == false then
    SemResult {
      ok     = false,
      report = AnalysisReport { errors = [], ok = false, type_map = [] },
    }
  else
    let report = analyze_program(parse.prog)
    SemResult { ok = report.ok, report = report }

# Step 4: IR 빌드 (AST → IRGraph)
function run_ir(parse: ParseResult2, sem: SemResult): IRResult =
  if sem.ok == false then
    IRResult { ok = false, graph = new_graph(), root = -1, error = "Semantic 실패" }
  else
    let b = new_builder()
    let r = build_ir_from_program(b, parse.prog)
    let b2    = fst(r)
    let root  = snd(r)
    let err   = thd_ir(r)
    if err != "" then
      IRResult { ok = false, graph = b2.graph, root = -1, error = err }
    else
      IRResult { ok = true, graph = b2.graph, root = root, error = "" }

# Step 5: Solve (수렴)
function run_solve(ir: IRResult): SolveResult =
  if ir.ok == false then
    SolveResult { ok = false, state_id = -1, steps = 0, error = ir.error }
  else
    let ctx = new_solver_ctx()
    solve_from_graph(ir.graph, ir.root, ctx)

# ============================================================================
# Part 3: 전체 파이프라인
# ============================================================================

function run_pipeline(src: String): PipelineResult =
  let empty_solve = SolveResult { ok = false, state_id = -1, steps = 0, error = "" }
  let empty_ir    = IRResult { ok = false, graph = new_graph(), root = -1, error = "" }
  let empty_sem   = SemResult { ok = false, report = AnalysisReport { errors = [], ok = false, type_map = [] } }
  let empty_parse = ParseResult2 { ok = false, prog = Program { nodes = [] }, errors = [] }

  # Step 1
  let lex = run_lex(src)
  if lex.ok == false then
    pipeline_fail(lex, empty_parse, empty_sem, empty_ir, empty_solve, "Lex 실패: " + lex.error)
  else

  # Step 2
  let parse = run_parse(lex)
  if parse.ok == false then
    pipeline_fail(lex, parse, empty_sem, empty_ir, empty_solve,
      "Parse 실패: " + first_parse_error(parse.errors))
  else

  # Step 3
  let sem = run_sem(parse)
  if sem.ok == false then
    pipeline_fail(lex, parse, sem, empty_ir, empty_solve,
      "Semantic 실패: " + first_sem_error(sem.report.errors))
  else

  # Step 4
  let ir = run_ir(parse, sem)
  if ir.ok == false then
    pipeline_fail(lex, parse, sem, ir, empty_solve, "IR 빌드 실패: " + ir.error)
  else

  # Step 5
  let solve = run_solve(ir)
  if solve.ok == false then
    pipeline_fail(lex, parse, sem, ir, solve, "수렴 실패: " + solve.error)
  else
    pipeline_ok(lex, parse, sem, ir, solve)

# ============================================================================
# Part 4: AST → IRGraph 변환
# ============================================================================

function build_ir_from_program(b: IRBuilder, prog: Program): (IRBuilder, Int, String) =
  if array_len(prog.nodes) == 0 then
    (b, -1, "빈 프로그램")
  else
    # 마지막 노드를 루트로 설정 (observe가 최종 수렴점)
    build_ir_nodes(b, prog.nodes, 0, -1)

function build_ir_nodes(b: IRBuilder, nodes: Array[ASTNode], idx: Int, last_id: Int): (IRBuilder, Int, String) =
  if idx >= array_len(nodes) then
    (b, last_id, "")
  else
    let node = array_get(nodes, idx)
    let r = build_ir_node(b, node)
    let b2  = fst3_ir(r)
    let nid = mid3_ir(r)
    let err = thd_ir(r)
    if err != "" then (b2, -1, err)
    else build_ir_nodes(b2, nodes, idx + 1, nid)

function build_ir_node(b: IRBuilder, node: ASTNode): (IRBuilder, Int, String) =
  let tag = node.tag
  if tag == "state" then
    let id = str_to_int(node.payload)
    let r = build_state(b, id)
    (fst(r), snd(r), "")

  else if tag == "observe" then
    let parts = split_colon_first(node.payload)
    let inner = ast_node(fst(parts), snd(parts), node.line, node.col)
    let r_inner = build_ir_node(b, inner)
    let b2 = fst3_ir(r_inner)
    let inner_id = mid3_ir(r_inner)
    let err = thd_ir(r_inner)
    if err != "" then (b2, -1, err)
    else
      let r = build_observe(b2, inner_id)
      (fst(r), snd(r), "")

  else if tag == "constrain" then
    let parts = split_pipe_sem(node.payload)
    let inner = payload_to_node(fst(parts), node.line, node.col)
    let cname = snd(parts)
    let r_inner = build_ir_node(b, inner)
    let b2 = fst3_ir(r_inner)
    let inner_id = mid3_ir(r_inner)
    let err = thd_ir(r_inner)
    if err != "" then (b2, -1, err)
    else
      let r = build_constrain(b2, inner_id, cname)
      (fst(r), snd(r), "")

  else if tag == "consume" then
    let parts = split_pipe_sem(node.payload)
    let inner = payload_to_node(fst(parts), node.line, node.col)
    let res_s = snd(parts)
    let nums  = split_comma_sem(res_s)
    let mem   = str_to_float_safe(fst(nums))
    let time_c  = str_to_float_safe(snd(nums))
    let r_inner = build_ir_node(b, inner)
    let b2 = fst3_ir(r_inner)
    let inner_id = mid3_ir(r_inner)
    let err = thd_ir(r_inner)
    if err != "" then (b2, -1, err)
    else
      let r = build_consume(b2, inner_id, mem, time_c)
      (fst(r), snd(r), "")

  else if tag == "evolve" then
    let parts = split_pipe_sem(node.payload)
    let inner = payload_to_node(fst(parts), node.line, node.col)
    let until = str_to_int(snd(parts))
    let r_inner = build_ir_node(b, inner)
    let b2 = fst3_ir(r_inner)
    let inner_id = mid3_ir(r_inner)
    let err = thd_ir(r_inner)
    if err != "" then (b2, -1, err)
    else
      let r = build_evolve(b2, inner_id, until)
      (fst(r), snd(r), "")

  else if tag == "compose" then
    let sides = split_double_pipe_sem(node.payload)
    let left  = payload_to_node(fst(sides), node.line, node.col)
    let right = payload_to_node(snd(sides), node.line, node.col)
    let r_left = build_ir_node(b, left)
    let b2 = fst3_ir(r_left)
    let left_id = mid3_ir(r_left)
    let err1 = thd_ir(r_left)
    if err1 != "" then (b2, -1, err1)
    else
      let r_right = build_ir_node(b2, right)
      let b3 = fst3_ir(r_right)
      let right_id = mid3_ir(r_right)
      let err2 = thd_ir(r_right)
      if err2 != "" then (b3, -1, err2)
      else
        let r = build_compose(b3, left_id, right_id)
        (fst(r), snd(r), "")

  else if tag == "let" then
    # let은 IR에서 상태 노드로 표현
    let eq_parts = split_first_char(node.payload, "=")
    let val_part = snd(eq_parts)
    let val_node = payload_to_node(val_part, node.line, node.col)
    build_ir_node(b, val_node)

  else if tag == "annot" then
    let parts = split_pipe_sem(node.payload)
    let inner = payload_to_node(snd(parts), node.line, node.col)
    build_ir_node(b, inner)

  else if tag == "int" || tag == "float" || tag == "string" || tag == "bool" || tag == "ident" then
    # 리터럴 → 즉시 상태 노드
    let r = graph_add_node(b.graph, IR_STATE, tag + "_" + node.payload, node.payload)
    let g2 = fst(r)
    let nid = snd(r)
    (IRBuilder { graph = g2 }, nid, "")

  else
    (b, -1, "IR 변환 불가 노드: " + tag)

# ============================================================================
# Part 5: IRGraph → Solver 연결
# 그래프의 루트 노드부터 수렴 탐색
# ============================================================================

function solve_from_graph(g: IRGraph, root_id: Int, ctx: SolverCtx): SolveResult =
  if root_id < 0 then
    SolveResult { ok = false, state_id = -1, steps = 0, error = "루트 노드 없음" }
  else
    match graph_find_node(g, root_id) {
      None    => SolveResult { ok = false, state_id = -1, steps = 0, error = "노드 없음: " + int_to_str(root_id) }
      Some(n) =>
        # IR 노드 종류 → solver 표현식으로 변환
        let tag = ir_node_to_expr_tag(n.kind)
        let payload = build_solver_payload(g, n, root_id)
        solve(tag, payload, ctx)
    }

function ir_node_to_expr_tag(kind: String): String =
  if kind == IR_STATE      then "state"
  else if kind == IR_OBSERVE    then "observe"
  else if kind == IR_CONSTRAINT then "constrain"
  else if kind == IR_RESOURCE   then "consume"
  else if kind == IR_TEMPORAL   then "evolve"
  else if kind == IR_COMPOSE    then "compose"
  else "state"

function build_solver_payload(g: IRGraph, n: IRNode, nid: Int): String =
  let in_edges = graph_in_edges(g, nid)
  if array_len(in_edges) == 0 then
    # 리프 노드: payload 직접 사용
    n.payload
  else if n.kind == IR_COMPOSE then
    # compose: 두 입력 노드
    let left_id  = (array_get(in_edges, 0)).from
    let right_id = (array_get(in_edges, 1)).from
    let left_tag  = ir_node_to_expr_tag((resolve_node(g, left_id)).kind)
    let right_tag = ir_node_to_expr_tag((resolve_node(g, right_id)).kind)
    left_tag  + ":" + int_to_str(left_id) +
    "||" +
    right_tag + ":" + int_to_str(right_id)
  else
    # 단일 입력
    let dep_id = (array_get(in_edges, 0)).from
    let dep_tag = ir_node_to_expr_tag((resolve_node(g, dep_id)).kind)
    dep_tag + ":" + int_to_str(dep_id) +
    (if n.payload != "" then "|" + n.payload else "")

function resolve_node(g: IRGraph, id: Int): IRNode =
  match graph_find_node(g, id) {
    Some(n) => n
    None    => IRNode { id = id, kind = IR_STATE, label = "", payload = int_to_str(id) }
  }

# ============================================================================
# Part 6: 파이프라인 리포트
# ============================================================================

function pipeline_report(r: PipelineResult): String =
  let status = if r.ok then "✅ 수렴 완료" else "❌ 실패"
  let lines = [
    "=== FVX Pipeline Report ===",
    "상태: " + status,
    "Lex:    " + (if r.lex.ok     then "OK (" + int_to_str(array_len(r.lex.tokens)) + " tokens)" else "FAIL"),
    "Parse:  " + (if r.parse.ok   then "OK (" + int_to_str(array_len(r.parse.prog.nodes)) + " nodes)" else "FAIL"),
    "Sem:    " + (if r.sem.ok     then "OK" else "FAIL (" + int_to_str(array_len(r.sem.report.errors)) + " errors)"),
    "IR:     " + (if r.ir.ok      then "OK (nodes=" + int_to_str(graph_node_count(r.ir.graph)) + " edges=" + int_to_str(graph_edge_count(r.ir.graph)) + ")" else "FAIL"),
    "Solve:  " + (if r.solve.ok   then "OK (state=" + int_to_str(r.converged_state) + " steps=" + int_to_str(r.total_steps) + ")" else "FAIL: " + r.solve.error),
    "===========================",
  ]
  join_lines(lines, 0, "")

function join_lines(lines: Array[String], idx: Int, acc: String): String =
  if idx >= array_len(lines) then acc
  else join_lines(lines, idx + 1, acc + array_get(lines, idx) + "\n")

# ============================================================================
# 헬퍼: 3-tuple (IRBuilder, Int, String)
# ============================================================================

function fst3_ir(t: (IRBuilder, Int, String)): IRBuilder = tuple3_first(t)
function mid3_ir(t: (IRBuilder, Int, String)): Int       = tuple3_second(t)
function thd_ir(t: (IRBuilder, Int, String)): String     = tuple3_third(t)

# ============================================================================
# 헬퍼: 에러 메시지 추출
# ============================================================================

function first_parse_error(errs: Array[ParseError]): String =
  if array_len(errs) == 0 then ""
  else (array_get(errs, 0)).msg

function first_sem_error(errs: Array[SemanticError]): String =
  if array_len(errs) == 0 then ""
  else (array_get(errs, 0)).msg

