# ============================================================================
# FVX Phase 4 — Pipeline End-to-End 테스트
# ============================================================================

# ============================================================================
# 헬퍼
# ============================================================================

function run(src: String): PipelineResult =
  run_pipeline(src)

function ok(src: String): Bool =
  (run(src)).ok

function fail(src: String): Bool =
  (run(src)).ok == false

function converged_to(src: String, expected_id: Int): Bool =
  let r = run(src)
  r.ok && r.converged_state == expected_id

function has_ir_nodes(src: String, n: Int): Bool =
  let r = run(src)
  r.ok && graph_node_count(r.ir.graph) == n

# ============================================================================
# Step 1: Lex 단계
# ============================================================================

function test_pipe_lex_ok(): Bool =
  let r = run("state(1)")
  r.lex.ok && array_len(r.lex.tokens) > 0

function test_pipe_lex_empty(): Bool =
  fail("")

# ============================================================================
# Step 2: Parse 단계
# ============================================================================

function test_pipe_parse_state(): Bool =
  let r = run("state(42)")
  r.parse.ok && array_len(r.parse.prog.nodes) == 1

function test_pipe_parse_observe(): Bool =
  let r = run("observe(state(5))")
  r.parse.ok && (array_get(r.parse.prog.nodes, 0)).tag == "observe"

function test_pipe_parse_multi(): Bool =
  let r = run("let a = state(1)\nobserve(a)")
  r.parse.ok && array_len(r.parse.prog.nodes) == 2

# ============================================================================
# Step 3: Semantic 단계
# ============================================================================

function test_pipe_sem_valid(): Bool =
  let r = run("observe(state(1))")
  r.sem.ok

function test_pipe_sem_time_violation(): Bool =
  # A4 위반: 역행
  let r = run("evolve(evolve(state(1), 100), 50)")
  r.sem.ok == false

function test_pipe_sem_resource_type(): Bool =
  let r = run("constrain(state(1), \"Int\")")
  r.sem.ok && string_contains(
    snd(array_last(r.sem.report.type_map)),
    "Constrained"
  )

# ============================================================================
# Step 4: IR 단계
# ============================================================================

function test_pipe_ir_state(): Bool =
  let r = run("state(1)")
  r.ir.ok && graph_node_count(r.ir.graph) == 1

function test_pipe_ir_observe(): Bool =
  # observe(state(1)) → IR_STATE + IR_OBSERVE = 2 nodes
  let r = run("observe(state(1))")
  r.ir.ok && graph_node_count(r.ir.graph) == 2

function test_pipe_ir_constrain(): Bool =
  # constrain(state(1), "Int") → IR_STATE + IR_CONSTRAINT = 2 nodes
  let r = run("constrain(state(1), \"Int\")")
  r.ir.ok && graph_node_count(r.ir.graph) == 2

function test_pipe_ir_compose(): Bool =
  # compose(state(1), state(2)) → 2 state + 1 compose = 3 nodes
  let r = run("compose(state(1), state(2))")
  r.ir.ok && graph_node_count(r.ir.graph) == 3

function test_pipe_ir_edges(): Bool =
  # observe(state(1)) → 1 edge: state→observe
  let r = run("observe(state(1))")
  r.ir.ok && graph_edge_count(r.ir.graph) == 1

# ============================================================================
# Step 5: Solve 단계 (수렴)
# ============================================================================

function test_pipe_solve_state(): Bool =
  let r = run("state(7)")
  r.ok && r.converged_state == 7

function test_pipe_solve_observe(): Bool =
  let r = run("observe(state(3))")
  r.ok && r.converged_state == 3

function test_pipe_solve_steps(): Bool =
  let r = run("observe(state(1))")
  r.ok && r.total_steps > 0

# ============================================================================
# 통합: 전체 파이프라인
# ============================================================================

function test_pipe_hello(): Bool =
  ok("observe(state(1))")

function test_pipe_constraint_demo(): Bool =
  # examples/constraint_demo.fl 요약판
  let src = "let s = constrain(state(1), \"Any\")\nobserve(compose(s, state(2)))"
  ok(src)

function test_pipe_temporal_demo(): Bool =
  # examples/temporal_demo.fl 요약판
  let src = "observe(constrain(evolve(state(1), 10), \"Any\"))"
  ok(src)

function test_pipe_consume_pipeline(): Bool =
  let src = "observe(consume(constrain(state(1), \"Any\"), 64.0, 10.0))"
  ok(src)

function test_pipe_full_chain(): Bool =
  # 전체 공리 순서대로: state → constrain → consume → evolve → observe
  let src = "observe(evolve(consume(constrain(state(1), \"Any\"), 10.0, 5.0), 20))"
  ok(src)

function test_pipe_report_format(): Bool =
  let r = run("observe(state(1))")
  let rep = pipeline_report(r)
  string_contains(rep, "수렴 완료") &&
  string_contains(rep, "Lex:") &&
  string_contains(rep, "Solve:")

# ============================================================================
# 에러 케이스
# ============================================================================

function test_pipe_error_bad_syntax(): Bool =
  fail("observe(state(")

function test_pipe_error_time_reverse(): Bool =
  fail("evolve(evolve(state(1), 50), 10)")

# ============================================================================
# 실행
# ============================================================================

function run_phase4_tests(): Int =
  let results = [
    # Lex
    ("Lex: 정상",                     test_pipe_lex_ok()),
    ("Lex: 빈 입력 실패",             test_pipe_lex_empty()),
    # Parse
    ("Parse: state",                  test_pipe_parse_state()),
    ("Parse: observe",                test_pipe_parse_observe()),
    ("Parse: 멀티 노드",              test_pipe_parse_multi()),
    # Semantic
    ("Sem: 정상",                     test_pipe_sem_valid()),
    ("Sem: 시간 역행 실패",           test_pipe_sem_time_violation()),
    ("Sem: 타입 추론",                test_pipe_sem_resource_type()),
    # IR
    ("IR: state 1노드",               test_pipe_ir_state()),
    ("IR: observe 2노드",             test_pipe_ir_observe()),
    ("IR: constrain 2노드",           test_pipe_ir_constrain()),
    ("IR: compose 3노드",             test_pipe_ir_compose()),
    ("IR: 엣지 생성",                 test_pipe_ir_edges()),
    # Solve
    ("Solve: state 수렴",             test_pipe_solve_state()),
    ("Solve: observe 수렴",           test_pipe_solve_observe()),
    ("Solve: 스텝 카운트",            test_pipe_solve_steps()),
    # 통합
    ("통합: hello fvx",               test_pipe_hello()),
    ("통합: constraint demo",         test_pipe_constraint_demo()),
    ("통합: temporal demo",           test_pipe_temporal_demo()),
    ("통합: consume pipeline",        test_pipe_consume_pipeline()),
    ("통합: 전체 공리 체인",          test_pipe_full_chain()),
    ("통합: report 형식",             test_pipe_report_format()),
    # 에러
    ("에러: 문법 오류",               test_pipe_error_bad_syntax()),
    ("에러: 시간 역행",               test_pipe_error_time_reverse()),
  ]
  count_results(results, 0, 0)

function count_results(results: Array[(String, Bool)], pass: Int, idx: Int): Int =
  if idx >= array_len(results) then
    let _ = print("=== Phase 4 결과: " + int_to_str(pass) + "/" + int_to_str(array_len(results)) + " PASS ===")
    pass
  else
    let item = array_get(results, idx)
    let name = fst(item)
    let ok_v = snd(item)
    let _ = if ok_v then print("[PASS] " + name)
            else print("[FAIL] " + name)
    count_results(results, if ok_v then pass + 1 else pass, idx + 1)

let passed = run_phase4_tests()

