# ============================================================================
# FVX — Fixed-Point Iteration Engine
#
# 수학적 기반:
#   f : L → L  (단조 함수, L = 완전 격자)
#   x₀ = ⊥  (최솟값)
#   xₙ₊₁ = f(xₙ)
#   수렴: xₙ₊₁ = xₙ  →  x* = fix(f)
#
# Tarski 정리: 단조 함수는 항상 최소 고정점을 가진다.
# 이것이 FVX Solver의 수학적 보장이다.
# ============================================================================

# ============================================================================
# Part 1: 격자 값 (Lattice Value)
# 완전 격자 L = ⊥ < Unknown < Partial < Stable < ⊤
# ============================================================================

let LAT_BOT     = 0   # ⊥ 최솟값 (미결정)
let LAT_UNKNOWN = 1   # 분석 시작
let LAT_PARTIAL = 2   # 부분 수렴
let LAT_STABLE  = 3   # 완전 수렴 (고정점)
let LAT_TOP     = 4   # ⊤ 최댓값 (충돌/에러)

record LatticeVal {
  level:    Int,      # LAT_* 상수
  state_id: Int,      # 수렴한 상태 ID (-1이면 미결정)
  label:    String,   # 디버그 레이블
}

function lat_bot(): LatticeVal =
  LatticeVal { level = LAT_BOT, state_id = -1, label = "⊥" }

function lat_unknown(label: String): LatticeVal =
  LatticeVal { level = LAT_UNKNOWN, state_id = -1, label = label }

function lat_partial(state_id: Int, label: String): LatticeVal =
  LatticeVal { level = LAT_PARTIAL, state_id = state_id, label = label }

function lat_stable(state_id: Int, label: String): LatticeVal =
  LatticeVal { level = LAT_STABLE, state_id = state_id, label = label }

function lat_top(label: String): LatticeVal =
  LatticeVal { level = LAT_TOP, state_id = -1, label = "⊤: " + label }

# 격자 합류 (join): a ⊔ b = max(a, b)
function lat_join(a: LatticeVal, b: LatticeVal): LatticeVal =
  if a.level >= b.level then a else b

# 격자 교환 (meet): a ⊓ b = min(a, b)
function lat_meet(a: LatticeVal, b: LatticeVal): LatticeVal =
  if a.level <= b.level then a else b

# 고정점 도달 여부: xₙ₊₁ = xₙ
function lat_eq(a: LatticeVal, b: LatticeVal): Bool =
  a.level == b.level && a.state_id == b.state_id

# 단조 증가 여부: a ≤ b
function lat_le(a: LatticeVal, b: LatticeVal): Bool =
  a.level <= b.level

# ============================================================================
# Part 2: 노드 상태 맵 (Node ID → LatticeVal)
# ============================================================================

record NodeState {
  entries: Array[(Int, LatticeVal)],
}

function new_node_state(): NodeState =
  NodeState { entries = [] }

function ns_set(ns: NodeState, node_id: Int, val: LatticeVal): NodeState =
  let filtered = ns_remove(ns.entries, node_id)
  NodeState { entries = array_append(filtered, (node_id, val)) }

function ns_get(ns: NodeState, node_id: Int): LatticeVal =
  find_lat(ns.entries, node_id)

function ns_remove(entries: Array[(Int, LatticeVal)], node_id: Int): Array[(Int, LatticeVal)] =
  if array_len(entries) == 0 then []
  else
    let head = array_head(entries)
    let tail = ns_remove(array_tail(entries), node_id)
    if fst(head) == node_id then tail
    else array_prepend(tail, head)

function find_lat(entries: Array[(Int, LatticeVal)], node_id: Int): LatticeVal =
  if array_len(entries) == 0 then lat_bot()
  else
    let head = array_head(entries)
    if fst(head) == node_id then snd(head)
    else find_lat(array_tail(entries), node_id)

# ============================================================================
# Part 3: Fixed-Point Iteration
#
# 알고리즘:
#   1. 모든 노드를 ⊥ 로 초기화
#   2. 각 노드에 전이 함수 f 적용
#   3. 변화 없을 때까지 반복 (고정점 도달)
#   4. 루트 노드의 값이 STABLE이면 수렴 성공
# ============================================================================

record FixpointCtx {
  max_iter:   Int,      # 최대 반복 횟수
  node_state: NodeState,
  changed:    Bool,     # 이번 라운드에 변화 있었나
  iter_count: Int,      # 현재 반복 횟수
}

function new_fixpoint_ctx(max_iter: Int): FixpointCtx =
  FixpointCtx {
    max_iter   = max_iter,
    node_state = new_node_state(),
    changed    = true,
    iter_count = 0,
  }

# 전이 함수 f(node) → LatticeVal
# 노드 종류에 따라 다른 전이 규칙 적용
function transfer(g: IRGraph, node: IRNode, ns: NodeState): LatticeVal =
  let kind = node.kind
  let in_edges = graph_in_edges(g, node.id)

  if kind == IR_STATE then
    # A1: 상태 노드는 즉시 STABLE
    let sid = str_to_int(node.payload)
    lat_stable(sid, "state_" + node.payload)

  else if kind == IR_CONSTRAINT then
    # A3: 입력이 STABLE 이상이면 제약 검사
    if array_len(in_edges) == 0 then lat_unknown("constraint_no_input")
    else
      let dep_val = ns_get(ns, (array_get(in_edges, 0)).from)
      if dep_val.level >= LAT_STABLE then
        lat_stable(dep_val.state_id, "constrained")
      else if dep_val.level >= LAT_PARTIAL then
        lat_partial(dep_val.state_id, "constraining")
      else
        lat_unknown("constraint_waiting")

  else if kind == IR_RESOURCE then
    # A2: 입력이 STABLE 이면 자원 소비 후 STABLE
    if array_len(in_edges) == 0 then lat_unknown("resource_no_input")
    else
      let dep_val = ns_get(ns, (array_get(in_edges, 0)).from)
      if dep_val.level >= LAT_STABLE then
        lat_stable(dep_val.state_id, "consumed")
      else
        lat_partial(dep_val.state_id, "consuming")

  else if kind == IR_TEMPORAL then
    # A4: 시간 전진 — 단조 증가
    if array_len(in_edges) == 0 then lat_unknown("temporal_no_input")
    else
      let dep_val = ns_get(ns, (array_get(in_edges, 0)).from)
      let until = str_to_int(node.payload)
      if dep_val.level >= LAT_STABLE then
        # 단조 증가 보장됨 (semantic에서 이미 검사)
        lat_stable(dep_val.state_id, "evolved_t" + int_to_str(until))
      else
        lat_partial(dep_val.state_id, "evolving")

  else if kind == IR_OBSERVE then
    # A5: 입력이 STABLE 이면 관측 완료
    if array_len(in_edges) == 0 then lat_unknown("observe_no_input")
    else
      let dep_val = ns_get(ns, (array_get(in_edges, 0)).from)
      if dep_val.level == LAT_STABLE then
        lat_stable(dep_val.state_id, "observed")
      else if dep_val.level == LAT_TOP then
        lat_top("관측 충돌")
      else
        lat_partial(dep_val.state_id, "observing")

  else if kind == IR_COMPOSE then
    # 합성: 두 입력의 join
    if array_len(in_edges) < 2 then
      if array_len(in_edges) == 1 then
        ns_get(ns, (array_get(in_edges, 0)).from)
      else
        lat_unknown("compose_no_input")
    else
      let left_val  = ns_get(ns, (array_get(in_edges, 0)).from)
      let right_val = ns_get(ns, (array_get(in_edges, 1)).from)
      # 두 입력 모두 STABLE이어야 compose STABLE
      if left_val.level == LAT_STABLE && right_val.level == LAT_STABLE then
        lat_stable(right_val.state_id, "composed")
      else if left_val.level == LAT_TOP || right_val.level == LAT_TOP then
        lat_top("compose 충돌")
      else
        lat_partial(
          if right_val.state_id >= 0 then right_val.state_id else left_val.state_id,
          "composing"
        )

  else
    lat_unknown("unknown_kind: " + kind)

# ============================================================================
# Part 4: 반복 라운드 실행
# ============================================================================

function fixpoint_round(g: IRGraph, ctx: FixpointCtx): FixpointCtx =
  iterate_nodes(g, ctx, g.nodes, false)

function iterate_nodes(g: IRGraph, ctx: FixpointCtx, nodes: Array[IRNode], changed: Bool): FixpointCtx =
  if array_len(nodes) == 0 then
    FixpointCtx {
      max_iter   = ctx.max_iter,
      node_state = ctx.node_state,
      changed    = changed,
      iter_count = ctx.iter_count,
    }
  else
    let node    = array_head(nodes)
    let old_val = ns_get(ctx.node_state, node.id)
    let new_val = transfer(g, node, ctx.node_state)
    # 단조 증가만 허용 (격자 성질)
    let updated = lat_join(old_val, new_val)
    let did_change = lat_eq(old_val, updated) == false
    let new_ns = if did_change then ns_set(ctx.node_state, node.id, updated)
                 else ctx.node_state
    let ctx2 = FixpointCtx {
      max_iter   = ctx.max_iter,
      node_state = new_ns,
      changed    = changed || did_change,
      iter_count = ctx.iter_count,
    }
    iterate_nodes(g, ctx2, array_tail(nodes), changed || did_change)

# ============================================================================
# Part 5: 고정점 탐색 메인 (Tarski 반복)
# ============================================================================

record FixpointResult {
  ok:          Bool,
  state_id:    Int,
  iter_count:  Int,
  final_state: NodeState,
  error:       String,
}

function fixpoint_ok(state_id: Int, iters: Int, ns: NodeState): FixpointResult =
  FixpointResult { ok = true, state_id = state_id, iter_count = iters, final_state = ns, error = "" }

function fixpoint_fail(msg: String, iters: Int, ns: NodeState): FixpointResult =
  FixpointResult { ok = false, state_id = -1, iter_count = iters, final_state = ns, error = msg }

function find_fixpoint(g: IRGraph, root_id: Int): FixpointResult =
  let ctx = new_fixpoint_ctx(100)
  iterate_until_stable(g, ctx, root_id)

function iterate_until_stable(g: IRGraph, ctx: FixpointCtx, root_id: Int): FixpointResult =
  if ctx.iter_count >= ctx.max_iter then
    fixpoint_fail("최대 반복 초과: " + int_to_str(ctx.max_iter), ctx.iter_count, ctx.node_state)
  else
    let ctx2 = fixpoint_round(g, ctx)
    let ctx3 = FixpointCtx {
      max_iter   = ctx2.max_iter,
      node_state = ctx2.node_state,
      changed    = ctx2.changed,
      iter_count = ctx2.iter_count + 1,
    }
    if ctx3.changed == false then
      # 고정점 도달
      let root_val = ns_get(ctx3.node_state, root_id)
      if root_val.level == LAT_STABLE then
        fixpoint_ok(root_val.state_id, ctx3.iter_count, ctx3.node_state)
      else if root_val.level == LAT_TOP then
        fixpoint_fail("수렴 충돌 (⊤)", ctx3.iter_count, ctx3.node_state)
      else
        fixpoint_fail(
          "고정점 도달했으나 불안정: level=" + int_to_str(root_val.level),
          ctx3.iter_count, ctx3.node_state
        )
    else
      # 아직 변화 중 → 계속
      let ctx4 = FixpointCtx {
        max_iter   = ctx3.max_iter,
        node_state = ctx3.node_state,
        changed    = false,   # 다음 라운드 초기화
        iter_count = ctx3.iter_count,
      }
      iterate_until_stable(g, ctx4, root_id)

# ============================================================================
# Part 6: SolveResult로 변환 (pipeline 연결)
# ============================================================================

function fixpoint_to_solve(r: FixpointResult): SolveResult =
  if r.ok then
    SolveResult {
      ok       = true,
      state_id = r.state_id,
      steps    = r.iter_count,
      error    = "",
    }
  else
    SolveResult {
      ok       = false,
      state_id = -1,
      steps    = r.iter_count,
      error    = r.error,
    }

# ============================================================================
# Part 7: 격자 상태 덤프 (디버깅)
# ============================================================================

function dump_node_state(g: IRGraph, ns: NodeState): String =
  dump_ns_nodes(g.nodes, ns, "")

function dump_ns_nodes(nodes: Array[IRNode], ns: NodeState, acc: String): String =
  if array_len(nodes) == 0 then acc
  else
    let n = array_head(nodes)
    let v = ns_get(ns, n.id)
    let level_str = if v.level == LAT_BOT     then "⊥"
                    else if v.level == LAT_UNKNOWN then "?"
                    else if v.level == LAT_PARTIAL then "~"
                    else if v.level == LAT_STABLE  then "✓"
                    else "⊤"
    let line = "  N" + int_to_str(n.id) + " [" + n.kind + "] " +
               level_str + " state=" + int_to_str(v.state_id) +
               " (" + v.label + ")\n"
    dump_ns_nodes(array_tail(nodes), ns, acc + line)

