# ============================================================================
# FVX — Constraint Propagator (제약 전파 엔진)
#
# 수학적 기반:
#   Arc Consistency (AC-3 알고리즘 변형)
#   워크리스트(worklist) 기반 전파
#
# 핵심 아이디어:
#   - 제약 변경 시 영향받는 이웃 노드를 큐에 추가
#   - 큐가 빌 때까지 전파 반복
#   - fixpoint.fl 과 연동: 전파 → 고정점 → 수렴
#
# 기존 solver.fl 의 순차 재귀와의 차이:
#   기존: DFS 순서로 하나씩 처리
#   신규: BFS 방식으로 제약 전파, 우선순위 큐 지원
# ============================================================================

# ============================================================================
# Part 1: 워크리스트 (처리 대기 노드 큐)
# ============================================================================

record Worklist {
  items:    Array[Int],   # 노드 ID 큐
  visited:  Array[Int],   # 이번 라운드 방문 노드
}

function new_worklist(): Worklist =
  Worklist { items = [], visited = [] }

function wl_push(wl: Worklist, node_id: Int): Worklist =
  if wl_contains(wl.items, node_id) then wl
  else
    Worklist {
      items   = array_append(wl.items, node_id),
      visited = wl.visited,
    }

function wl_pop(wl: Worklist): (Worklist, Int) =
  if array_len(wl.items) == 0 then (wl, -1)
  else
    let head = array_get(wl.items, 0)
    let rest = array_tail(wl.items)
    (Worklist {
      items   = rest,
      visited = array_append(wl.visited, head),
    }, head)

function wl_empty(wl: Worklist): Bool =
  array_len(wl.items) == 0

function wl_contains(items: Array[Int], node_id: Int): Bool =
  if array_len(items) == 0 then false
  else if array_get(items, 0) == node_id then true
  else wl_contains(array_tail(items), node_id)

# ============================================================================
# Part 2: 전파 컨텍스트
# ============================================================================

record PropCtx {
  graph:      IRGraph,
  node_state: NodeState,
  worklist:   Worklist,
  rounds:     Int,
  max_rounds: Int,
  log:        Array[String],   # 전파 로그
}

function new_prop_ctx(g: IRGraph): PropCtx =
  # 모든 노드를 초기 워크리스트에 추가
  let wl = init_worklist(g.nodes, new_worklist())
  PropCtx {
    graph      = g,
    node_state = new_node_state(),
    worklist   = wl,
    rounds     = 0,
    max_rounds = 500,
    log        = [],
  }

function init_worklist(nodes: Array[IRNode], wl: Worklist): Worklist =
  if array_len(nodes) == 0 then wl
  else
    let head = array_head(nodes)
    init_worklist(array_tail(nodes), wl_push(wl, head.id))

function prop_log(ctx: PropCtx, msg: String): PropCtx =
  PropCtx {
    graph      = ctx.graph,
    node_state = ctx.node_state,
    worklist   = ctx.worklist,
    rounds     = ctx.rounds,
    max_rounds = ctx.max_rounds,
    log        = array_append(ctx.log, msg),
  }

# ============================================================================
# Part 3: 단일 노드 전파 스텝
# ============================================================================

function propagate_node(ctx: PropCtx, node_id: Int): PropCtx =
  match graph_find_node(ctx.graph, node_id) {
    None    => ctx
    Some(n) =>
      let old_val = ns_get(ctx.node_state, node_id)
      let new_val = transfer(ctx.graph, n, ctx.node_state)
      let updated = lat_join(old_val, new_val)

      if lat_eq(old_val, updated) then
        ctx   # 변화 없음: 전파 불필요
      else
        # 값 갱신 + 영향받는 이웃 노드 큐에 추가
        let ns2 = ns_set(ctx.node_state, node_id, updated)
        let neighbors = get_affected_neighbors(ctx.graph, node_id)
        let wl2 = enqueue_neighbors(ctx.worklist, neighbors)
        let ctx2 = PropCtx {
          graph      = ctx.graph,
          node_state = ns2,
          worklist   = wl2,
          rounds     = ctx.rounds,
          max_rounds = ctx.max_rounds,
          log        = ctx.log,
        }
        prop_log(ctx2,
          "N" + int_to_str(node_id) + ": " +
          int_to_str(old_val.level) + " → " + int_to_str(updated.level))
  }

# 영향받는 이웃: 이 노드를 입력으로 받는 노드들
function get_affected_neighbors(g: IRGraph, node_id: Int): Array[Int] =
  collect_targets(graph_out_edges(g, node_id), [])

function collect_targets(edges: Array[IREdge], acc: Array[Int]): Array[Int] =
  if array_len(edges) == 0 then acc
  else
    let e = array_head(edges)
    collect_targets(array_tail(edges), array_append(acc, e.to))

function enqueue_neighbors(wl: Worklist, neighbors: Array[Int]): Worklist =
  if array_len(neighbors) == 0 then wl
  else
    let head = array_get(neighbors, 0)
    enqueue_neighbors(wl_push(wl, head), array_tail(neighbors))

# ============================================================================
# Part 4: 전파 루프 (워크리스트 소진까지)
# ============================================================================

function propagate_all(ctx: PropCtx): PropCtx =
  if wl_empty(ctx.worklist) then ctx
  else if ctx.rounds >= ctx.max_rounds then ctx
  else
    let pop_r = wl_pop(ctx.worklist)
    let wl2   = fst(pop_r)
    let nid   = snd(pop_r)
    if nid < 0 then ctx
    else
      let ctx2 = PropCtx {
        graph      = ctx.graph,
        node_state = ctx.node_state,
        worklist   = wl2,
        rounds     = ctx.rounds + 1,
        max_rounds = ctx.max_rounds,
        log        = ctx.log,
      }
      let ctx3 = propagate_node(ctx2, nid)
      propagate_all(ctx3)

# ============================================================================
# Part 5: 전파 결과 → SolveResult
# ============================================================================

record PropResult {
  ok:         Bool,
  state_id:   Int,
  rounds:     Int,
  log:        Array[String],
  error:      String,
}

function run_propagator(g: IRGraph, root_id: Int): PropResult =
  let ctx = new_prop_ctx(g)
  let ctx2 = propagate_all(ctx)
  let root_val = ns_get(ctx2.node_state, root_id)

  if root_val.level == LAT_STABLE then
    PropResult {
      ok       = true,
      state_id = root_val.state_id,
      rounds   = ctx2.rounds,
      log      = ctx2.log,
      error    = "",
    }
  else if root_val.level == LAT_TOP then
    PropResult {
      ok       = false,
      state_id = -1,
      rounds   = ctx2.rounds,
      log      = ctx2.log,
      error    = "전파 충돌 (⊤)",
    }
  else
    PropResult {
      ok       = false,
      state_id = -1,
      rounds   = ctx2.rounds,
      log      = ctx2.log,
      error    = "전파 미완료: level=" + int_to_str(root_val.level),
    }

function prop_to_solve(r: PropResult): SolveResult =
  SolveResult {
    ok       = r.ok,
    state_id = r.state_id,
    steps    = r.rounds,
    error    = r.error,
  }

# ============================================================================
# Part 6: 전파 로그 덤프
# ============================================================================

function dump_prop_log(r: PropResult): String =
  let header = "=== Propagation Log [" + int_to_str(r.rounds) + " rounds] ===\n"
  dump_log_items(r.log, 0, header)

function dump_log_items(log: Array[String], idx: Int, acc: String): String =
  if idx >= array_len(log) then acc
  else
    dump_log_items(log, idx + 1, acc + "  " + array_get(log, idx) + "\n")

