# ============================================================================
# FVX Phase 5 — Solver 고도화 테스트
# fixpoint.fl + propagator.fl + scheduler.fl
# ============================================================================

# ============================================================================
# 헬퍼: IR 그래프 직접 구성
# ============================================================================

function make_state_graph(state_id: Int): (IRGraph, Int) =
  let b = new_builder()
  let r = build_state(b, state_id)
  (fst(r).graph, snd(r))

function make_observe_graph(state_id: Int): (IRGraph, Int) =
  let b = new_builder()
  let r1 = build_state(b, state_id)
  let b2 = fst(r1)
  let s  = snd(r1)
  let r2 = build_observe(b2, s)
  (fst(r2).graph, snd(r2))

function make_constrain_graph(state_id: Int, cname: String): (IRGraph, Int) =
  let b = new_builder()
  let r1 = build_state(b, state_id)
  let b2 = fst(r1)
  let s  = snd(r1)
  let r2 = build_constrain(b2, s, cname)
  (fst(r2).graph, snd(r2))

function make_compose_graph(id1: Int, id2: Int): (IRGraph, Int) =
  let b = new_builder()
  let r1 = build_state(b, id1)
  let b2 = fst(r1)
  let n1 = snd(r1)
  let r2 = build_state(b2, id2)
  let b3 = fst(r2)
  let n2 = snd(r2)
  let r3 = build_compose(b3, n1, n2)
  (fst(r3).graph, snd(r3))

function make_full_graph(): (IRGraph, Int) =
  # observe(constrain(consume(state(1), 10, 5), "Any"))
  let b = new_builder()
  let r1 = build_state(b, 1)
  let b2 = fst(r1)
  let s  = snd(r1)
  let r2 = build_consume(b2, s, 10.0, 5.0)
  let b3 = fst(r2)
  let c  = snd(r2)
  let r3 = build_constrain(b3, c, "Any")
  let b4 = fst(r3)
  let k  = snd(r3)
  let r4 = build_observe(b4, k)
  (fst(r4).graph, snd(r4))

# ============================================================================
# 격자 테스트
# ============================================================================

function test_lat_order(): Bool =
  let bot = lat_bot()
  let unk = lat_unknown("x")
  let par = lat_partial(1, "x")
  let sta = lat_stable(1, "x")
  let top = lat_top("x")
  lat_le(bot, unk) && lat_le(unk, par) && lat_le(par, sta) && lat_le(sta, top)

function test_lat_join(): Bool =
  let a = lat_partial(1, "a")
  let b = lat_stable(2, "b")
  let j = lat_join(a, b)
  j.level == LAT_STABLE

function test_lat_meet(): Bool =
  let a = lat_partial(1, "a")
  let b = lat_stable(2, "b")
  let m = lat_meet(a, b)
  m.level == LAT_PARTIAL

function test_lat_eq(): Bool =
  let a = lat_stable(5, "x")
  let b = lat_stable(5, "y")
  lat_eq(a, b)

# ============================================================================
# 전이 함수 테스트
# ============================================================================

function test_transfer_state(): Bool =
  let r = make_state_graph(42)
  let g  = fst(r)
  let nid = snd(r)
  let ns = new_node_state()
  let node = match graph_find_node(g, nid) { Some(n) => n  None => IRNode { id=0, kind="", label="", payload="" } }
  let val = transfer(g, node, ns)
  val.level == LAT_STABLE && val.state_id == 42

function test_transfer_observe_waiting(): Bool =
  let r = make_observe_graph(1)
  let g   = fst(r)
  let obs = snd(r)
  let ns = new_node_state()   # 모든 노드 ⊥
  let node = match graph_find_node(g, obs) { Some(n) => n  None => IRNode { id=0, kind="", label="", payload="" } }
  let val = transfer(g, node, ns)
  # 입력이 ⊥이므로 observe도 미결정
  val.level < LAT_STABLE

function test_transfer_observe_stable(): Bool =
  let r = make_observe_graph(7)
  let g   = fst(r)
  let obs = snd(r)
  # 입력 노드(state)를 STABLE로 사전 설정
  let state_nid = 1  # build_state가 1번 노드 생성
  let ns = ns_set(new_node_state(), state_nid, lat_stable(7, "state_7"))
  let node = match graph_find_node(g, obs) { Some(n) => n  None => IRNode { id=0, kind="", label="", payload="" } }
  let val = transfer(g, node, ns)
  val.level == LAT_STABLE && val.state_id == 7

# ============================================================================
# Fixed-Point Iteration 테스트
# ============================================================================

function test_fixpoint_state(): Bool =
  let r = make_state_graph(3)
  let result = fixpoint_to_solve(find_fixpoint(fst(r), snd(r)))
  result.ok && result.state_id == 3

function test_fixpoint_observe(): Bool =
  let r = make_observe_graph(5)
  let result = fixpoint_to_solve(find_fixpoint(fst(r), snd(r)))
  result.ok && result.state_id == 5

function test_fixpoint_constrain(): Bool =
  let r = make_constrain_graph(10, "Int")
  let result = fixpoint_to_solve(find_fixpoint(fst(r), snd(r)))
  result.ok && result.state_id == 10

function test_fixpoint_compose(): Bool =
  let r = make_compose_graph(1, 2)
  let result = fixpoint_to_solve(find_fixpoint(fst(r), snd(r)))
  result.ok && result.state_id == 2

function test_fixpoint_full(): Bool =
  let r = make_full_graph()
  let result = fixpoint_to_solve(find_fixpoint(fst(r), snd(r)))
  result.ok && result.state_id == 1

function test_fixpoint_iter_count(): Bool =
  let r = make_full_graph()
  let fp = find_fixpoint(fst(r), snd(r))
  fp.ok && fp.iter_count > 0 && fp.iter_count <= 20

# ============================================================================
# Propagator 테스트
# ============================================================================

function test_prop_state(): Bool =
  let r = make_state_graph(7)
  let result = prop_to_solve(run_propagator(fst(r), snd(r)))
  result.ok && result.state_id == 7

function test_prop_observe(): Bool =
  let r = make_observe_graph(9)
  let result = prop_to_solve(run_propagator(fst(r), snd(r)))
  result.ok && result.state_id == 9

function test_prop_compose(): Bool =
  let r = make_compose_graph(3, 4)
  let result = prop_to_solve(run_propagator(fst(r), snd(r)))
  result.ok && result.state_id == 4

function test_prop_log(): Bool =
  let r = make_observe_graph(1)
  let pr = run_propagator(fst(r), snd(r))
  pr.ok && array_len(pr.log) > 0

function test_prop_full(): Bool =
  let r = make_full_graph()
  let result = prop_to_solve(run_propagator(fst(r), snd(r)))
  result.ok

# ============================================================================
# Scheduler 테스트
# ============================================================================

function test_sched_hybrid_small(): Bool =
  let r = make_observe_graph(1)
  let result = schedule(fst(r), snd(r))
  result.ok && result.state_id == 1

function test_sched_eager(): Bool =
  let r = make_full_graph()
  let result = schedule_with(fst(r), snd(r), eager_strategy())
  result.ok && result.strategy == STRAT_EAGER

function test_sched_lazy(): Bool =
  let r = make_full_graph()
  let result = schedule_with(fst(r), snd(r), lazy_strategy())
  result.ok && result.strategy == STRAT_LAZY

function test_sched_total_work(): Bool =
  let r = make_full_graph()
  let result = schedule(fst(r), snd(r))
  result.ok && result.total_work > 0

function test_sched_report_format(): Bool =
  let r = make_observe_graph(1)
  let result = schedule(fst(r), snd(r))
  let rep = schedule_report(result)
  string_contains(rep, "수렴") && string_contains(rep, "총 작업량")

function test_sched_empty_graph(): Bool =
  let result = schedule(new_graph(), -1)
  result.ok == false

# ============================================================================
# A5 관측 불변성: EAGER == LAZY 동일 결과
# ============================================================================

function test_invariance_eager_lazy(): Bool =
  let r = make_full_graph()
  let g = fst(r)
  let root = snd(r)
  let eager_r = schedule_with(g, root, eager_strategy())
  let lazy_r  = schedule_with(g, root, lazy_strategy())
  # 경로(rounds/iters)는 달라도 state_id는 같아야 함
  eager_r.ok && lazy_r.ok &&
  eager_r.state_id == lazy_r.state_id

# ============================================================================
# 파이프라인 통합: scheduler 사용
# ============================================================================

function test_pipe_with_scheduler(): Bool =
  let src = "observe(compose(constrain(state(1), \"Any\"), state(2)))"
  let r = parse_program(src)
  let prog = fst(r)
  let sem = analyze_program(prog)
  if sem.ok == false then false
  else
    let b = new_builder()
    let ir_r = build_ir_from_program(b, prog)
    let b2   = fst3_ir(ir_r)
    let root = mid3_ir(ir_r)
    if root < 0 then false
    else
      let sched_r = schedule(b2.graph, root)
      sched_r.ok && sched_r.state_id == 2

# ============================================================================
# 실행
# ============================================================================

function run_phase5_tests(): Int =
  let results = [
    # 격자
    ("격자 순서 ⊥<? <~<✓<⊤",         test_lat_order()),
    ("격자 join",                       test_lat_join()),
    ("격자 meet",                       test_lat_meet()),
    ("격자 eq",                         test_lat_eq()),
    # 전이 함수
    ("전이: state → STABLE",            test_transfer_state()),
    ("전이: observe 대기",              test_transfer_observe_waiting()),
    ("전이: observe 수렴",              test_transfer_observe_stable()),
    # Fixed-Point
    ("고정점: state",                   test_fixpoint_state()),
    ("고정점: observe",                 test_fixpoint_observe()),
    ("고정점: constrain",               test_fixpoint_constrain()),
    ("고정점: compose",                 test_fixpoint_compose()),
    ("고정점: 전체 체인",               test_fixpoint_full()),
    ("고정점: 반복 횟수",               test_fixpoint_iter_count()),
    # Propagator
    ("전파: state",                     test_prop_state()),
    ("전파: observe",                   test_prop_observe()),
    ("전파: compose",                   test_prop_compose()),
    ("전파: 로그 생성",                 test_prop_log()),
    ("전파: 전체 체인",                 test_prop_full()),
    # Scheduler
    ("스케줄러: hybrid 소형",           test_sched_hybrid_small()),
    ("스케줄러: eager",                 test_sched_eager()),
    ("스케줄러: lazy",                  test_sched_lazy()),
    ("스케줄러: 총 작업량",             test_sched_total_work()),
    ("스케줄러: 리포트 형식",           test_sched_report_format()),
    ("스케줄러: 빈 그래프 실패",        test_sched_empty_graph()),
    # A5 불변성
    ("A5 불변성: eager=lazy 결과",      test_invariance_eager_lazy()),
    # 통합
    ("통합: 파이프라인+스케줄러",       test_pipe_with_scheduler()),
  ]
  count_results(results, 0, 0)

function count_results(results: Array[(String, Bool)], pass: Int, idx: Int): Int =
  if idx >= array_len(results) then
    let _ = print("=== Phase 5 결과: " + int_to_str(pass) + "/" + int_to_str(array_len(results)) + " PASS ===")
    pass
  else
    let item = array_get(results, idx)
    let name = fst(item)
    let ok_v  = snd(item)
    let _ = if ok_v then print("[PASS] " + name)
            else print("[FAIL] " + name)
    count_results(results, if ok_v then pass + 1 else pass, idx + 1)

let passed = run_phase5_tests()

