# ============================================================================
# REPL 상태 테스트
# ============================================================================

function test_repl_new_state(): Bool =
  let s = new_repl_state()
  array_len(s.history) == 0 && s.counter == 0

function test_repl_eval_ok(): Bool =
  let s = new_repl_state()
  let r = repl_eval(s, "observe(state(1))")
  let new_s = fst(r)
  let out   = snd(r)
  new_s.counter == 1 &&
  array_len(new_s.history) == 1 &&
  string_contains(out, "state(1)")

function test_repl_eval_help(): Bool =
  let s = new_repl_state()
  let r = repl_eval(s, ":help")
  string_contains(snd(r), "REPL")

function test_repl_history(): Bool =
  let s = new_repl_state()
  let r1 = repl_eval(s, "observe(state(1))")
  let s2 = fst(r1)
  let r2 = repl_eval(s2, "observe(state(2))")
  let s3 = fst(r2)
  array_len(s3.history) == 2

function test_repl_clear(): Bool =
  let s = new_repl_state()
  let r1 = repl_eval(s, "observe(state(1))")
  let s2 = fst(r1)
  let r2 = repl_eval(s2, ":clear")
  let s3 = fst(r2)
  s3.counter == 0 && array_len(s3.history) == 0

function test_repl_empty_line(): Bool =
  let s = new_repl_state()
  let r = repl_eval(s, "")
  snd(r) == ""

