    ("run: 성공 리포트",        test_run_report_ok()),
    ("run: 실패 리포트",        test_run_report_fail()),
    ("run: 스텝 카운트",        test_run_steps()),
    # cmd_check
    ("check: 정상",             test_check_valid()),
    ("check: 타입 맵",          test_check_types()),
    ("check: 시간 위반",        test_check_fail_time()),
    ("check: 성공 포맷",        test_check_format_ok()),
    ("check: 실패 포맷",        test_check_format_fail()),
    # cmd_ir
